/**
 * Unified InputManager for pointer (mouse/touch/stylus) and keyboard.
 * Normalizes all input to pointer events. No hover-dependent mechanics.
 */

export interface PointerEvent {
  x: number;
  y: number;
  type: 'down' | 'move' | 'up' | 'click';
  button: number; // 0 = left/primary, 1 = middle, 2 = right
  timestamp: number;
  isTouch: boolean;
}

export interface KeyboardEvent {
  key: string;
  code: string;
  type: 'down' | 'up';
  timestamp: number;
  ctrlKey: boolean;
  shiftKey: boolean;
  altKey: boolean;
  metaKey: boolean;
}

export interface InputManager {
  /** Current pointer position */
  pointer: { x: number; y: number } | null;
  /** Whether primary pointer button is down */
  isPointerDown: boolean;
  /** Last click position */
  lastClick: { x: number; y: number } | null;
  /** Whether a drag is in progress */
  isDragging: boolean;
  /** Drag start position */
  dragStart: { x: number; y: number } | null;
  /** Keys currently pressed */
  pressedKeys: Set<string>;
  /** Callbacks */
  onPointerDown?: (event: PointerEvent) => void;
  onPointerMove?: (event: PointerEvent) => void;
  onPointerUp?: (event: PointerEvent) => void;
  onClick?: (event: PointerEvent) => void;
  onDragStart?: (event: PointerEvent) => void;
  onDragMove?: (event: PointerEvent) => void;
  onDragEnd?: (event: PointerEvent) => void;
  onKeyDown?: (event: KeyboardEvent) => void;
  onKeyUp?: (event: KeyboardEvent) => void;
}

/**
 * Creates a new InputManager
 */
export function createInputManager(): InputManager {
  return {
    pointer: null,
    isPointerDown: false,
    lastClick: null,
    isDragging: false,
    dragStart: null,
    pressedKeys: new Set(),
  };
}

const DRAG_THRESHOLD = 8; // pixels

/**
 * Attaches input listeners to an element
 */
export function attachInputListeners(
  manager: InputManager,
  element: HTMLElement,
  getWorldCoords: (clientX: number, clientY: number) => { x: number; y: number }
): () => void {
  const pointerDownHandler = (e: PointerEvent | TouchEvent) => {
    const isTouch = 'touches' in e;
    const clientX = isTouch ? (e as TouchEvent).touches[0].clientX : (e as PointerEvent).clientX;
    const clientY = isTouch ? (e as TouchEvent).touches[0].clientY : (e as PointerEvent).clientY;

    const coords = getWorldCoords(clientX, clientY);
    const timestamp = performance.now();

    manager.pointer = coords;
    manager.isPointerDown = true;
    manager.dragStart = { ...coords };
    manager.isDragging = false;

    const event: PointerEvent = {
      x: coords.x,
      y: coords.y,
      type: 'down',
      button: isTouch ? 0 : (e as PointerEvent).button,
      timestamp,
      isTouch,
    };

    if (manager.onPointerDown) manager.onPointerDown(event);
  };

  const pointerMoveHandler = (e: PointerEvent | TouchEvent) => {
    const isTouch = 'touches' in e;
    const clientX = isTouch ? (e as TouchEvent).touches[0].clientX : (e as PointerEvent).clientX;
    const clientY = isTouch ? (e as TouchEvent).touches[0].clientY : (e as PointerEvent).clientY;

    const coords = getWorldCoords(clientX, clientY);
    const timestamp = performance.now();

    manager.pointer = coords;

    const event: PointerEvent = {
      x: coords.x,
      y: coords.y,
      type: 'move',
      button: 0,
      timestamp,
      isTouch,
    };

    if (manager.onPointerMove) manager.onPointerMove(event);

    // Check for drag
    if (manager.isPointerDown && manager.dragStart) {
      const dx = coords.x - manager.dragStart.x;
      const dy = coords.y - manager.dragStart.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (!manager.isDragging && distance > DRAG_THRESHOLD) {
        manager.isDragging = true;
        if (manager.onDragStart) {
          manager.onDragStart({
            ...event,
            type: 'down',
          });
        }
      }

      if (manager.isDragging && manager.onDragMove) {
        manager.onDragMove(event);
      }
    }
  };

  const pointerUpHandler = (e: PointerEvent | TouchEvent) => {
    const isTouch = 'touches' in e || 'changedTouches' in e;
    const clientX = isTouch
      ? ('changedTouches' in e ? (e as TouchEvent).changedTouches[0].clientX : (e as TouchEvent).touches[0]?.clientX || 0)
      : (e as PointerEvent).clientX;
    const clientY = isTouch
      ? ('changedTouches' in e ? (e as TouchEvent).changedTouches[0].clientY : (e as TouchEvent).touches[0]?.clientY || 0)
      : (e as PointerEvent).clientY;

    const coords = getWorldCoords(clientX, clientY);
    const timestamp = performance.now();

    const wasDragging = manager.isDragging;

    manager.isPointerDown = false;

    const event: PointerEvent = {
      x: coords.x,
      y: coords.y,
      type: 'up',
      button: 0,
      timestamp,
      isTouch,
    };

    if (manager.onPointerUp) manager.onPointerUp(event);

    if (wasDragging && manager.onDragEnd) {
      manager.onDragEnd(event);
    } else if (!wasDragging) {
      // Click event
      manager.lastClick = { ...coords };
      const clickEvent: PointerEvent = { ...event, type: 'click' };
      if (manager.onClick) manager.onClick(clickEvent);
    }

    manager.isDragging = false;
    manager.dragStart = null;
  };

  const pointerLeaveHandler = () => {
    manager.isPointerDown = false;
    manager.isDragging = false;
    manager.dragStart = null;
  };

  const keyDownHandler = (e: KeyboardEvent) => {
    manager.pressedKeys.add(e.code);

    const event: KeyboardEvent = {
      key: e.key,
      code: e.code,
      type: 'down',
      timestamp: performance.now(),
      ctrlKey: e.ctrlKey,
      shiftKey: e.shiftKey,
      altKey: e.altKey,
      metaKey: e.metaKey,
    };

    if (manager.onKeyDown) manager.onKeyDown(event);
  };

  const keyUpHandler = (e: KeyboardEvent) => {
    manager.pressedKeys.delete(e.code);

    const event: KeyboardEvent = {
      key: e.key,
      code: e.code,
      type: 'up',
      timestamp: performance.now(),
      ctrlKey: e.ctrlKey,
      shiftKey: e.shiftKey,
      altKey: e.altKey,
      metaKey: e.metaKey,
    };

    if (manager.onKeyUp) manager.onKeyUp(event);
  };

  // Attach listeners
  element.addEventListener('pointerdown', pointerDownHandler as EventListener);
  element.addEventListener('pointermove', pointerMoveHandler as EventListener);
  element.addEventListener('pointerup', pointerUpHandler as EventListener);
  element.addEventListener('pointerleave', pointerLeaveHandler);
  element.addEventListener('pointercancel', pointerLeaveHandler);

  // Touch events for better mobile support
  element.addEventListener('touchstart', pointerDownHandler, { passive: false });
  element.addEventListener('touchmove', pointerMoveHandler, { passive: false });
  element.addEventListener('touchend', pointerUpHandler);
  element.addEventListener('touchcancel', pointerLeaveHandler);

  window.addEventListener('keydown', keyDownHandler);
  window.addEventListener('keyup', keyUpHandler);

  // Return cleanup function
  return () => {
    element.removeEventListener('pointerdown', pointerDownHandler as EventListener);
    element.removeEventListener('pointermove', pointerMoveHandler as EventListener);
    element.removeEventListener('pointerup', pointerUpHandler as EventListener);
    element.removeEventListener('pointerleave', pointerLeaveHandler);
    element.removeEventListener('pointercancel', pointerLeaveHandler);
    element.removeEventListener('touchstart', pointerDownHandler);
    element.removeEventListener('touchmove', pointerMoveHandler);
    element.removeEventListener('touchend', pointerUpHandler);
    element.removeEventListener('touchcancel', pointerLeaveHandler);
    window.removeEventListener('keydown', keyDownHandler);
    window.removeEventListener('keyup', keyUpHandler);
  };
}

/**
 * Checks if a key is currently pressed
 */
export function isKeyPressed(manager: InputManager, code: string): boolean {
  return manager.pressedKeys.has(code);
}

/**
 * Gets the current drag distance
 */
export function getDragDistance(manager: InputManager): number {
  if (!manager.dragStart || !manager.pointer) return 0;
  const dx = manager.pointer.x - manager.dragStart.x;
  const dy = manager.pointer.y - manager.dragStart.y;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Gets drag direction vector
 */
export function getDragVector(manager: InputManager): { x: number; y: number } | null {
  if (!manager.dragStart || !manager.pointer) return null;
  return {
    x: manager.pointer.x - manager.dragStart.x,
    y: manager.pointer.y - manager.dragStart.y,
  };
}

/**
 * Resets input state
 */
export function resetInputManager(manager: InputManager): void {
  manager.pointer = null;
  manager.isPointerDown = false;
  manager.lastClick = null;
  manager.isDragging = false;
  manager.dragStart = null;
  manager.pressedKeys.clear();
}

/**
 * Creates a mock InputManager for testing
 */
export function createMockInputManager(): InputManager {
  return createInputManager();
}