/**
 * Renders the 12x12 game field with grid lines and perimeter arrows.
 */

import { Field, GRID_SIZE, Point } from '../core/types.js';
import { drawSprite, getSprite, type Sprite } from './sprites.js';

export interface RenderFieldConfig {
  /** Color of grid lines */
  gridLineColor: string;
  /** Width of grid lines */
  gridLineWidth: number;
  /** Background color */
  backgroundColor: string;
  /** Perimeter border color */
  perimeterColor: string;
  /** Width of perimeter border */
  perimeterWidth: number;
  /** Perimeter arrow color */
  perimeterArrowColor: string;
}

const DEFAULT_CONFIG: RenderFieldConfig = {
  gridLineColor: 'rgba(200, 200, 200, 0.3)',
  gridLineWidth: 1,
  backgroundColor: '#ecf0f1',
  perimeterColor: '#2c3e50',
  perimeterWidth: 2,
  perimeterArrowColor: '#000000',
};

/**
 * Renders the complete game field
 */
export function renderField(
  ctx: CanvasRenderingContext2D,
  field: Field,
  cellSize: number,
  offsetX: number,
  offsetY: number,
  config: Partial<RenderFieldConfig> = {},
  spriteManager?: { getSprite: typeof getSprite }
): void {
  const cfg = { ...DEFAULT_CONFIG, ...config };

  // Draw background
  ctx.fillStyle = cfg.backgroundColor;
  ctx.fillRect(offsetX, offsetY, GRID_SIZE * cellSize, GRID_SIZE * cellSize);

  // Draw grid lines
  renderGridLines(ctx, cellSize, offsetX, offsetY, cfg);

  // Draw perimeter border
  renderPerimeterBorder(ctx, cellSize, offsetX, offsetY, cfg);

  // Draw perimeter arrows
  renderPerimeterArrows(ctx, cellSize, offsetX, offsetY, cfg, spriteManager);
}

/**
 * Renders grid lines
 */
function renderGridLines(
  ctx: CanvasRenderingContext2D,
  cellSize: number,
  offsetX: number,
  offsetY: number,
  cfg: RenderFieldConfig
): void {
  ctx.strokeStyle = cfg.gridLineColor;
  ctx.lineWidth = cfg.gridLineWidth;

  // Vertical lines
  for (let col = 0; col <= GRID_SIZE; col++) {
    const x = offsetX + col * cellSize;
    ctx.beginPath();
    ctx.moveTo(x, offsetY);
    ctx.lineTo(x, offsetY + GRID_SIZE * cellSize);
    ctx.stroke();
  }

  // Horizontal lines
  for (let row = 0; row <= GRID_SIZE; row++) {
    const y = offsetY + row * cellSize;
    ctx.beginPath();
    ctx.moveTo(offsetX, y);
    ctx.lineTo(offsetX + GRID_SIZE * cellSize, y);
    ctx.stroke();
  }
}

/**
 * Renders the perimeter border
 */
function renderPerimeterBorder(
  ctx: CanvasRenderingContext2D,
  cellSize: number,
  offsetX: number,
  offsetY: number,
  cfg: RenderFieldConfig
): void {
  ctx.strokeStyle = cfg.perimeterColor;
  ctx.lineWidth = cfg.perimeterWidth;
  ctx.strokeRect(
    offsetX,
    offsetY,
    GRID_SIZE * cellSize,
    GRID_SIZE * cellSize
  );
}

/**
 * Renders arrows on the perimeter pointing outward
 */
function renderPerimeterArrows(
  ctx: CanvasRenderingContext2D,
  cellSize: number,
  offsetX: number,
  offsetY: number,
  cfg: RenderFieldConfig,
  spriteManager?: { getSprite: typeof getSprite }
): void {
  const arrowSize = cellSize * 0.4;
  const perimeterOffset = cellSize * 0.15;

  // Get arrow sprite or draw placeholder
  const arrowSprite = spriteManager?.getSprite('perimeter_arrow') ?? null;

  // Top and bottom rows (pointing up/down)
  for (let col = 0; col < GRID_SIZE; col++) {
    // Top arrow (pointing up)
    const topX = offsetX + (col + 0.5) * cellSize;
    const topY = offsetY - perimeterOffset;

    if (arrowSprite) {
      drawSprite(ctx, arrowSprite, topX - arrowSize / 2, topY - arrowSize / 2, arrowSize, arrowSize);
    } else {
      drawArrowPlaceholder(ctx, topX, topY, 'north', arrowSize, cfg.perimeterArrowColor);
    }

    // Bottom arrow (pointing down)
    const bottomX = offsetX + (col + 0.5) * cellSize;
    const bottomY = offsetY + GRID_SIZE * cellSize + perimeterOffset;

    if (arrowSprite) {
      ctx.save();
      ctx.translate(bottomX, bottomY);
      ctx.rotate(Math.PI);
      drawSprite(ctx, arrowSprite, -arrowSize / 2, -arrowSize / 2, arrowSize, arrowSize);
      ctx.restore();
    } else {
      drawArrowPlaceholder(ctx, bottomX, bottomY, 'south', arrowSize, cfg.perimeterArrowColor);
    }
  }

  // Left and right columns (pointing left/right), excluding corners
  for (let row = 1; row < GRID_SIZE - 1; row++) {
    // Left arrow (pointing left)
    const leftX = offsetX - perimeterOffset;
    const leftY = offsetY + (row + 0.5) * cellSize;

    if (arrowSprite) {
      ctx.save();
      ctx.translate(leftX, leftY);
      ctx.rotate(-Math.PI / 2);
      drawSprite(ctx, arrowSprite, -arrowSize / 2, -arrowSize / 2, arrowSize, arrowSize);
      ctx.restore();
    } else {
      drawArrowPlaceholder(ctx, leftX, leftY, 'west', arrowSize, cfg.perimeterArrowColor);
    }

    // Right arrow (pointing right)
    const rightX = offsetX + GRID_SIZE * cellSize + perimeterOffset;
    const rightY = offsetY + (row + 0.5) * cellSize;

    if (arrowSprite) {
      ctx.save();
      ctx.translate(rightX, rightY);
      ctx.rotate(Math.PI / 2);
      drawSprite(ctx, arrowSprite, -arrowSize / 2, -arrowSize / 2, arrowSize, arrowSize);
      ctx.restore();
    } else {
      drawArrowPlaceholder(ctx, rightX, rightY, 'east', arrowSize, cfg.perimeterArrowColor);
    }
  }
}

/**
 * Draws an arrow placeholder (triangle)
 */
function drawArrowPlaceholder(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  direction: 'north' | 'south' | 'east' | 'west',
  size: number,
  color: string
): void {
  ctx.fillStyle = color;
  ctx.beginPath();

  const half = size / 2;

  switch (direction) {
    case 'north':
      ctx.moveTo(x, y - half);
      ctx.lineTo(x - half, y + half);
      ctx.lineTo(x + half, y + half);
      break;
    case 'south':
      ctx.moveTo(x, y + half);
      ctx.lineTo(x - half, y - half);
      ctx.lineTo(x + half, y - half);
      break;
    case 'east':
      ctx.moveTo(x + half, y);
      ctx.lineTo(x - half, y - half);
      ctx.lineTo(x - half, y + half);
      break;
    case 'west':
      ctx.moveTo(x - half, y);
      ctx.lineTo(x + half, y - half);
      ctx.lineTo(x + half, y + half);
      break;
  }

  ctx.closePath();
  ctx.fill();
}

/**
 * Converts screen coordinates to grid cell coordinates
 */
export function screenToGrid(
  screenX: number,
  screenY: number,
  cellSize: number,
  offsetX: number,
  offsetY: number
): Point | null {
  const gridX = Math.floor((screenX - offsetX) / cellSize);
  const gridY = Math.floor((screenY - offsetY) / cellSize);

  if (gridX < 0 || gridX >= GRID_SIZE || gridY < 0 || gridY >= GRID_SIZE) {
    return null;
  }

  return { row: gridY, col: gridX };
}

/**
 * Converts grid coordinates to screen center position
 */
export function gridToScreen(
  cell: Point,
  cellSize: number,
  offsetX: number,
  offsetY: number
): { x: number; y: number } {
  return {
    x: offsetX + (cell.col + 0.5) * cellSize,
    y: offsetY + (cell.row + 0.5) * cellSize,
  };
}

/**
 * Gets the screen rectangle for a grid cell
 */
export function getCellRect(
  cell: Point,
  cellSize: number,
  offsetX: number,
  offsetY: number
): { x: number; y: number; width: number; height: number } {
  return {
    x: offsetX + cell.col * cellSize,
    y: offsetY + cell.row * cellSize,
    width: cellSize,
    height: cellSize,
  };
}

/**
 * Checks if a point is within the field bounds
 */
export function isPointInField(
  x: number,
  y: number,
  cellSize: number,
  offsetX: number,
  offsetY: number
): boolean {
  return (
    x >= offsetX &&
    x <= offsetX + GRID_SIZE * cellSize &&
    y >= offsetY &&
    y <= offsetY + GRID_SIZE * cellSize
  );
}