/**
 * Deterministic PRNG using Linear Congruential Generator (LCG).
 * Ensures byte-identical replay across platforms.
 * Uses Park-Miller algorithm with 31-bit modulus.
 */

import { SeededRandom } from './types.js';

/**
 * LCG constants (Park-Miller "minimal standard")
 * Modulus: 2^31 - 1 (Mersenne prime)
 * Multiplier: 16807 (7^5)
 */
const MODULUS = 2147483647; // 2^31 - 1
const MULTIPLIER = 16807;
const INCREMENT = 0; // Pure multiplicative LCG

/**
 * Creates a new seeded random number generator.
 * @param seed Initial seed value (1 to MODULUS-1)
 */
export function createSeededRandom(seed: number): SeededRandom {
  // Ensure seed is in valid range
  let state = Math.floor(Math.abs(seed)) % MODULUS;
  if (state === 0) state = 1; // LCG cannot have 0 state

  return {
    next(): number {
      state = (state * MULTIPLIER) % MODULUS;
      return state / MODULUS; // Returns [0, 1)
    },

    nextInt(min: number, max: number): number {
      if (min > max) throw new Error('min must be <= max');
      const range = max - min + 1;
      return min + Math.floor(this.next() * range);
    },

    reset(seed: number): void {
      state = Math.floor(Math.abs(seed)) % MODULUS;
      if (state === 0) state = 1;
    },

    getState(): number {
      return state;
    },

    setState(newState: number): void {
      state = Math.floor(Math.abs(newState)) % MODULUS;
      if (state === 0) state = 1;
    },
  };
}

/**
 * Creates a PRNG from a string seed (hashes the string)
 */
export function createSeededRandomFromString(seedStr: string): SeededRandom {
  let hash = 0;
  for (let i = 0; i < seedStr.length; i++) {
    const char = seedStr.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return createSeededRandom(Math.abs(hash) || 1);
}

/**
 * Default deterministic seed for consistent testing
 */
export const DEFAULT_SEED = 12345;

/**
 * Creates a default PRNG for testing
 */
export function createDefaultPRNG(): SeededRandom {
  return createSeededRandom(DEFAULT_SEED);
}

/**
 * Utility: pick a random element from an array
 */
export function pickRandom<T>(prng: SeededRandom, array: readonly T[]): T {
  if (array.length === 0) throw new Error('Cannot pick from empty array');
  const index = prng.nextInt(0, array.length - 1);
  return array[index];
}

/**
 * Utility: shuffle an array in place (Fisher-Yates)
 */
export function shuffleArray<T>(prng: SeededRandom, array: T[]): T[] {
  for (let i = array.length - 1; i > 0; i--) {
    const j = prng.nextInt(0, i);
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}