/**
 * Core types and interfaces for AppleFactory simulation.
 * This module has zero browser/DOM dependencies.
 */

// Grid constants
export const GRID_SIZE = 12;
export const TOTAL_CELLS = GRID_SIZE * GRID_SIZE;

// Game timing constants (all in milliseconds)
export const TICK_RATE_MS = 1000 / 60; // 60 Hz fixed timestep

// Piece constants
export const SOURCE_INITIAL_APPLES = 8;
export const SOURCE_APPLES_PER_CELL = 2;
export const CONVEYOR_MOVE_TIME_MS = 1000; // 1 cell per second
export const PROCESSOR_TIME_MS = 2000; // 2 seconds per apple
export const CONTAINER_CAPACITY = 12;

// Order constants
export const ORDER_MIN_QUANTITY = 20;
export const ORDER_MAX_QUANTITY = 30;
export const VICTORY_ORDERS = 5;
export const INITIAL_APPLES = 15;
export const INITIAL_SLICES = 0;

// Shop constants
export const FREE_SHOP_SLOTS = 3;
export const CONVEYOR_REROLL_COST = 2;

// Direction enum
export type Direction = 'north' | 'south' | 'east' | 'west';

// Cell coordinate on the field
export interface Point {
  row: number;
  col: number;
}

// Resource type
export type ResourceType = 'apple' | 'apple_slice';

// Piece type categories
export type PieceType = 'source' | 'conveyor' | 'processor' | 'container';

// Conveyor variant types
export type ConveyorVariant = '1x1' | '1x2' | 'corner';

// Port information
export interface PortInfo {
  row: number;
  col: number;
  direction: Direction;
  type: 'input' | 'output';
  pieceId: string;
}

// Resource in transit or on a piece
export interface Resource {
  id: string;
  type: ResourceType;
  currentCell: Point;
  currentPieceId: string | null;
  nextCell: Point | null;
  queueIndex: number;
  generationTime: number;
}

// Connection between ports
export interface Connection {
  id: string;
  sourcePieceId: string;
  sourcePort: PortInfo;
  targetPieceId: string; // 'perimeter' for field boundary
  targetPort: PortInfo;
  active: boolean;
  resourceQueue: Resource[];
}

// Piece variant definition (one of 8 orientations/mirrors)
export interface PieceVariant {
  id: string;
  type: PieceType;
  shape: Point[]; // Cells occupied relative to anchor
  ports: PortInfo[];
  conveyorVariant?: ConveyorVariant;
}

// Placed piece on the field
export interface Piece {
  id: string;
  type: PieceType;
  variant: PieceVariant;
  position: Point; // Anchor cell
  resources: Partial<Record<ResourceType, number>>;
  connectedPorts: Map<string, Connection>;
  active: boolean;
  // Processor-specific state
  processorInput: Resource | null;
  processorOutput: Resource | null;
  processorProgress: number; // 0-100, processing progress
  // Container-specific state
  containerType: ResourceType | null;
  containerStorage: Resource[];
}

// Field cell
export interface Cell {
  piece: Piece | null;
  resource: Resource | null;
}

// 12x12 game field
export interface Field {
  width: number;
  height: number;
  cells: Cell[][];
}

// Order definition
export interface Order {
  id: string;
  requiredResourceType: ResourceType;
  requiredQuantity: number;
  generatedAt: number;
  completedAt: number | null;
  buttonHighlighted: boolean;
}

// Shop slot
export interface ShopSlot {
  piece: PieceVariant | null;
}

// Shop state
export interface Shop {
  freeSlots: ShopSlot[];
  conveyorSlot: ShopSlot;
  allTypesSlot: ShopSlot;
  rerollCooldown: number;
  firstCycle: boolean;
}

// Complete game state
export interface GameState {
  field: Field;
  resources: {
    apples: number;
    appleSlices: number;
  };
  orders: {
    current: Order;
    completed: number;
  };
  shop: Shop;
  timestamp: number;
  tickCount: number;
  seed: number;
}

// Tick result
export interface SimulationTickResult {
  newState: GameState;
  movedResources: Resource[];
  blockages: Array<{
    chainId: string;
    blockedPort: PortInfo;
    blockedResources: Resource[];
  }>;
  pieceActivities: Array<{
    pieceId: string;
    actions: ('produced' | 'consumed' | 'transferred')[];
  }>;
}

// User action types
export type UserActionType =
  | 'place_piece'
  | 'move_piece'
  | 'click_piece'
  | 'pause_piece'
  | 'restart_game'
  | 'reroll_slot'
  | 'complete_order';

export interface UserAction {
  id: string;
  type: UserActionType;
  timestamp: number;
  target?: string;
  position?: Point;
  parameters?: Record<string, unknown>;
}

// Seeded PRNG interface
export interface SeededRandom {
  next(): number; // Returns [0, 1)
  nextInt(min: number, max: number): number; // Returns [min, max]
  reset(seed: number): void;
  getState(): number;
  setState(state: number): void;
}

// Validation result
export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

// Resource unit counter
export type ResourceCount = {
  [K in ResourceType]: number;
};
