/**
 * Order system: order generation, completion, and victory tracking.
 */

import { SeededRandom, Order, ResourceType } from './types.js';

let orderIdCounter = 0;
export function generateOrderId(): string {
  return `order_${++orderIdCounter}`;
}

/**
 * Generates a new random order (20-30 quantity of apples or apple slices)
 */
export function generateOrder(prng: SeededRandom): Order {
  const quantity = prng.nextInt(20, 30);
  const type: ResourceType = prng.nextInt(0, 1) === 0 ? 'apple' : 'apple_slice';

  return {
    id: generateOrderId(),
    requiredResourceType: type,
    requiredQuantity: quantity,
    generatedAt: Date.now(),
    completedAt: null,
    buttonHighlighted: false,
  };
}

/**
 * Checks if current order can be completed with available resources
 */
export function checkOrderHighlight(order: Order, resources: { apples: number; appleSlices: number }): boolean {
  const available = order.requiredResourceType === 'apple'
    ? resources.apples
    : resources.appleSlices;

  return available >= order.requiredQuantity;
}

/**
 * Completes the current order if possible
 * Returns the new order or null if cannot complete
 */
export function completeOrder(
  order: Order,
  resources: { apples: number; appleSlices: number }
): { newOrder: Order; resourcesDeducted: boolean } | null {
  const available = order.requiredResourceType === 'apple'
    ? resources.apples
    : resources.appleSlices;

  if (available < order.requiredQuantity) {
    return null;
  }

  // Deduct resources
  if (order.requiredResourceType === 'apple') {
    resources.apples -= order.requiredQuantity;
  } else {
    resources.appleSlices -= order.requiredQuantity;
  }

  // Mark order completed
  order.completedAt = Date.now();

  // Generate new order
  const newOrder = generateOrder({ next: () => Math.random() } as SeededRandom); // Will be replaced with actual PRNG

  return {
    newOrder,
    resourcesDeducted: true,
  };
}

/**
 * Increments order completion counter
 */
export function incrementOrderCounter(completed: number): number {
  return completed + 1;
}

/**
 * Checks victory condition (5 completed orders)
 */
export function checkVictory(completed: number): boolean {
  return completed >= 5;
}

/**
 * Ticks order system - checks if order button should be highlighted
 */
export function tickOrders(
  state: {
    orders: { current: Order; completed: number };
    resources: { apples: number; appleSlices: number };
  }
): void {
  const { orders, resources } = state;
  const currentOrder = orders.current;

  // Check highlight status
  currentOrder.buttonHighlighted = checkOrderHighlight(currentOrder, resources);
}

/**
 * Gets order progress as percentage (0-100)
 */
export function getOrderProgress(order: Order, resources: { apples: number; appleSlices: number }): number {
  const available = order.requiredResourceType === 'apple'
    ? resources.apples
    : resources.appleSlices;

  return Math.min(100, Math.floor((available / order.requiredQuantity) * 100));
}

/**
 * Serializes order state
 */
export function serializeOrder(order: Order): any {
  return {
    id: order.id,
    requiredResourceType: order.requiredResourceType,
    requiredQuantity: order.requiredQuantity,
    generatedAt: order.generatedAt,
    completedAt: order.completedAt,
    buttonHighlighted: order.buttonHighlighted,
  };
}

/**
 * Deserializes order from saved state
 */
export function deserializeOrder(data: any): Order {
  return {
    id: data.id,
    requiredResourceType: data.requiredResourceType,
    requiredQuantity: data.requiredQuantity,
    generatedAt: data.generatedAt,
    completedAt: data.completedAt,
    buttonHighlighted: data.buttonHighlighted,
  };
}

/**
 * Serializes orders state
 */
export function serializeOrdersState(data: { current: Order; completed: number }): any {
  return {
    current: serializeOrder(data.current),
    completed: data.completed,
  };
}

/**
 * Deserializes orders state
 */
export function deserializeOrdersState(data: any): { current: Order; completed: number } {
  return {
    current: deserializeOrder(data.current),
    completed: data.completed,
  };
}

/**
 * Gets display text for order
 */
export function getOrderDisplayText(order: Order): string {
  const resourceName = order.requiredResourceType === 'apple' ? 'apples' : 'apple slices';
  return `Deliver ${order.requiredQuantity} ${resourceName}`;
}