/**
 * AssetManager for loading and managing game sprites.
 * Supports placeholder shapes and hot-swapping with designer PNGs.
 */

export interface Sprite {
  name: string;
  image: HTMLImageElement | HTMLCanvasElement;
  width: number;
  height: number;
  loaded: boolean;
}

export interface AssetManager {
  sprites: Map<string, Sprite>;
  placeholders: Map<string, HTMLCanvasElement>;
  loadQueue: Promise<void>[];
  onSpriteLoad?: (name: string) => void;
}

/**
 * Creates a new AssetManager
 */
export function createAssetManager(): AssetManager {
  return {
    sprites: new Map(),
    placeholders: new Map(),
    loadQueue: [],
  };
}

/**
 * Creates a placeholder canvas for a sprite
 */
export function createPlaceholderSprite(
  name: string,
  width: number,
  height: number,
  drawFn: (ctx: CanvasRenderingContext2D) => void
): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d')!;
  drawFn(ctx);
  return canvas;
}

/**
 * Pre-renders all placeholder shapes
 */
export function generatePlaceholders(manager: AssetManager): void {
  const dpr = window.devicePixelRatio || 1;
  const baseSize = 64;

  // Apple (red circle)
  manager.placeholders.set('apple', createPlaceholderSprite('apple', baseSize, baseSize, ctx => {
    ctx.fillStyle = '#e74c3c';
    ctx.beginPath();
    ctx.arc(baseSize / 2, baseSize / 2, baseSize * 0.4, 0, Math.PI * 2);
    ctx.fill();
  }));

  // Apple Slice (white semicircle with red edge)
  manager.placeholders.set('apple_slice', createPlaceholderSprite('apple_slice', baseSize, baseSize, ctx => {
    // White semicircle
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(baseSize / 2, baseSize / 2, baseSize * 0.35, -Math.PI / 2, Math.PI / 2);
    ctx.fill();
    // Red peel edge
    ctx.strokeStyle = '#e74c3c';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(baseSize / 2, baseSize / 2, baseSize * 0.35, -Math.PI / 2, Math.PI / 2);
    ctx.stroke();
  }));

  // Source piece (light red background)
  manager.placeholders.set('source', createPlaceholderSprite('source', baseSize * 2, baseSize * 2, ctx => {
    ctx.fillStyle = '#fadbd8';
    ctx.fillRect(0, 0, baseSize * 2, baseSize * 2);
    ctx.strokeStyle = '#e74c3c';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize * 2, baseSize * 2);
  }));

  // Conveyor (muted gray-blue)
  manager.placeholders.set('conveyor', createPlaceholderSprite('conveyor', baseSize * 2, baseSize, ctx => {
    ctx.fillStyle = '#7f8c8d';
    ctx.fillRect(0, 0, baseSize * 2, baseSize);
    ctx.strokeStyle = '#5d6d7e';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize * 2, baseSize);
  }));

  // Conveyor 1x1
  manager.placeholders.set('conveyor_1x1', createPlaceholderSprite('conveyor_1x1', baseSize, baseSize, ctx => {
    ctx.fillStyle = '#7f8c8d';
    ctx.fillRect(0, 0, baseSize, baseSize);
    ctx.strokeStyle = '#5d6d7e';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize, baseSize);
  }));

  // Conveyor Corner
  manager.placeholders.set('conveyor_corner', createPlaceholderSprite('conveyor_corner', baseSize * 2, baseSize * 2, ctx => {
    ctx.fillStyle = '#7f8c8d';
    // L-shape
    ctx.fillRect(0, 0, baseSize * 2, baseSize);
    ctx.fillRect(baseSize, baseSize, baseSize, baseSize);
    ctx.strokeStyle = '#5d6d7e';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize * 2, baseSize);
    ctx.strokeRect(baseSize, baseSize, baseSize, baseSize);
  }));

  // Processor (black with conveyor center)
  manager.placeholders.set('processor', createPlaceholderSprite('processor', baseSize, baseSize * 3, ctx => {
    ctx.fillStyle = '#2c3e50';
    ctx.fillRect(0, 0, baseSize, baseSize * 3);
    // Center conveyor cell
    ctx.fillStyle = '#7f8c8d';
    ctx.fillRect(0, baseSize, baseSize, baseSize);
    ctx.strokeStyle = '#1a252f';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize, baseSize * 3);
  }));

  // Container (beige with brown outline and hatching)
  manager.placeholders.set('container', createPlaceholderSprite('container', baseSize * 3, baseSize * 2, ctx => {
    ctx.fillStyle = '#f5e6cc';
    ctx.fillRect(0, 0, baseSize * 3, baseSize * 2);
    // Brown outline
    ctx.strokeStyle = '#8b7355';
    ctx.lineWidth = 3;
    ctx.strokeRect(0, 0, baseSize * 3, baseSize * 2);
    // Diagonal hatching
    ctx.strokeStyle = '#a68b6b';
    ctx.lineWidth = 1;
    for (let i = -baseSize * 2; i < baseSize * 4; i += 20) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i + baseSize * 2, baseSize * 2);
      ctx.stroke();
    }
  }));

  // Port arrows (output and input)
  manager.placeholders.set('arrow_output', createPlaceholderSprite('arrow_output', baseSize, baseSize, ctx => {
    ctx.fillStyle = '#000000';
    ctx.beginPath();
    ctx.moveTo(baseSize * 0.5, baseSize * 0.2);
    ctx.lineTo(baseSize * 0.3, baseSize * 0.5);
    ctx.lineTo(baseSize * 0.7, baseSize * 0.5);
    ctx.closePath();
    ctx.fill();
  }));

  manager.placeholders.set('arrow_input', createPlaceholderSprite('arrow_input', baseSize, baseSize, ctx => {
    ctx.fillStyle = '#000000';
    ctx.beginPath();
    ctx.moveTo(baseSize * 0.5, baseSize * 0.8);
    ctx.lineTo(baseSize * 0.3, baseSize * 0.5);
    ctx.lineTo(baseSize * 0.7, baseSize * 0.5);
    ctx.closePath();
    ctx.fill();
  }));

  // Perimeter arrow
  manager.placeholders.set('perimeter_arrow', createPlaceholderSprite('perimeter_arrow', baseSize, baseSize, ctx => {
    ctx.fillStyle = '#000000';
    ctx.beginPath();
    ctx.moveTo(baseSize * 0.5, baseSize * 0.1);
    ctx.lineTo(baseSize * 0.3, baseSize * 0.4);
    ctx.lineTo(baseSize * 0.7, baseSize * 0.4);
    ctx.closePath();
    ctx.fill();
  }));

  // UI button backgrounds
  manager.placeholders.set('button_normal', createPlaceholderSprite('button_normal', baseSize * 3, baseSize, ctx => {
    ctx.fillStyle = '#34495e';
    ctx.fillRect(0, 0, baseSize * 3, baseSize);
    ctx.strokeStyle = '#2c3e50';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize * 3, baseSize);
  }));

  manager.placeholders.set('button_hover', createPlaceholderSprite('button_hover', baseSize * 3, baseSize, ctx => {
    ctx.fillStyle = '#4a677e';
    ctx.fillRect(0, 0, baseSize * 3, baseSize);
    ctx.strokeStyle = '#34495e';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize * 3, baseSize);
  }));

  manager.placeholders.set('button_disabled', createPlaceholderSprite('button_disabled', baseSize * 3, baseSize, ctx => {
    ctx.fillStyle = '#5d6d7e';
    ctx.fillRect(0, 0, baseSize * 3, baseSize);
    ctx.strokeStyle = '#5d6d7e';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize * 3, baseSize);
  }));

  manager.placeholders.set('button_highlighted', createPlaceholderSprite('button_highlighted', baseSize * 3, baseSize, ctx => {
    ctx.fillStyle = '#27ae60';
    ctx.fillRect(0, 0, baseSize * 3, baseSize);
    ctx.strokeStyle = '#1e8449';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, baseSize * 3, baseSize);
  }));
}

/**
 * Loads a sprite from URL (for designer PNGs)
 * Hot-swaps placeholder with loaded image
 */
export function loadSprite(
  manager: AssetManager,
  name: string,
  url: string
): Promise<void> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const sprite: Sprite = {
        name,
        image: img,
        width: img.naturalWidth,
        height: img.naturalHeight,
        loaded: true,
      };
      manager.sprites.set(name, sprite);
      if (manager.onSpriteLoad) manager.onSpriteLoad(name);
      resolve();
    };
    img.onerror = () => reject(new Error(`Failed to load sprite: ${url}`));
    img.src = url;
  });
}

/**
 * Gets a sprite (placeholder or loaded)
 */
export function getSprite(manager: AssetManager, name: string): Sprite | null {
  // Return loaded sprite if available
  if (manager.sprites.has(name)) {
    return manager.sprites.get(name)!;
  }

  // Return placeholder if available
  if (manager.placeholders.has(name)) {
    const placeholder = manager.placeholders.get(name)!;
    return {
      name,
      image: placeholder,
      width: placeholder.width,
      height: placeholder.height,
      loaded: true,
    };
  }

  return null;
}

/**
 * Checks if a sprite is loaded (not placeholder)
 */
export function isSpriteLoaded(manager: AssetManager, name: string): boolean {
  const sprite = manager.sprites.get(name);
  return sprite?.loaded === true;
}

/**
 * Preloads multiple sprites
 */
export async function preloadSprites(
  manager: AssetManager,
  sprites: Array<{ name: string; url: string }>
): Promise<void> {
  await Promise.all(
    sprites.map(s => loadSprite(manager, s.name, s.url))
  );
}

/**
 * Draws a sprite to canvas context
 */
export function drawSprite(
  ctx: CanvasRenderingContext2D,
  sprite: Sprite | null,
  x: number,
  y: number,
  width?: number,
  height?: number
): void {
  if (!sprite) return;

  const w = width ?? sprite.width;
  const h = height ?? sprite.height;

  ctx.drawImage(sprite.image, x, y, w, h);
}

/**
 * Draws a sprite rotated around its center
 */
export function drawSpriteRotated(
  ctx: CanvasRenderingContext2D,
  sprite: Sprite | null,
  x: number,
  y: number,
  angle: number,
  width?: number,
  height?: number
): void {
  if (!sprite) return;

  const w = width ?? sprite.width;
  const h = height ?? sprite.height;

  ctx.save();
  ctx.translate(x + w / 2, y + h / 2);
  ctx.rotate(angle);
  ctx.drawImage(sprite.image, -w / 2, -h / 2, w, h);
  ctx.restore();
}

/**
 * Creates a sprite sheet from individual sprites
 */
export function createSpriteSheet(
  sprites: Map<string, Sprite>,
  padding: number = 2
): HTMLCanvasElement {
  const keys = Array.from(sprites.keys());
  const maxWidth = Math.max(...keys.map(k => sprites.get(k)!.width));
  const maxHeight = Math.max(...keys.map(k => sprites.get(k)!.height));

  const cols = Math.ceil(Math.sqrt(keys.length));
  const rows = Math.ceil(keys.length / cols);

  const canvas = document.createElement('canvas');
  canvas.width = (maxWidth + padding) * cols;
  canvas.height = (maxHeight + padding) * rows;

  const ctx = canvas.getContext('2d')!;

  keys.forEach((key, i) => {
    const sprite = sprites.get(key)!;
    const col = i % cols;
    const row = Math.floor(i / cols);
    ctx.drawImage(sprite.image, col * (maxWidth + padding), row * (maxHeight + padding), sprite.width, sprite.height);
  });

  return canvas;
}