/**
 * Piece type definitions, shapes, and port maps.
 * All 8 variants (4 orientations × horizontal mirror) for each piece type.
 */

import { PieceType, PieceVariant, Point, Direction, ConveyorVariant } from './types.js';

/**
 * Generates a unique piece ID
 */
let pieceIdCounter = 0;
export function generatePieceId(): string {
  return `piece_${++pieceIdCounter}_${Date.now()}`;
}

/**
 * Generates a unique variant ID
 */
let variantIdCounter = 0;
export function generateVariantId(): string {
  return `variant_${++variantIdCounter}`;
}

/**
 * Rotates a shape 90 degrees clockwise
 */
function rotateShape(shape: Point[]): Point[] {
  return shape.map(p => ({ row: p.col, col: -p.row }));
}

/**
 * Mirrors a shape horizontally
 */
function mirrorShape(shape: Point[]): Point[] {
  return shape.map(p => ({ row: p.row, col: -p.col }));
}

/**
 * Rotates a port 90 degrees clockwise
 */
function rotatePort(port: { direction: Direction; row: number; col: number }): { direction: Direction; row: number; col: number } {
  const dirMap: Record<Direction, Direction> = {
    north: 'east',
    east: 'south',
    south: 'west',
    west: 'north',
  };
  return {
    direction: dirMap[port.direction],
    row: port.col,
    col: -port.row,
  };
}

/**
 * Mirrors a port horizontally
 */
function mirrorPort(port: { direction: Direction; row: number; col: number }): { direction: Direction; row: number; col: number } {
  const dirMap: Record<Direction, Direction> = {
    north: 'north',
    east: 'west',
    south: 'south',
    west: 'east',
  };
  return {
    direction: dirMap[port.direction],
    row: port.row,
    col: -port.col,
  };
}

/**
 * Generates all 8 variants (4 rotations × 2 mirrors) of a piece
 */
function generateVariants(
  type: PieceType,
  baseShape: Point[],
  basePorts: Array<{ direction: Direction; row: number; col: number; type: 'input' | 'output' }>,
  conveyorVariant?: ConveyorVariant
): PieceVariant[] {
  const variants: PieceVariant[] = [];

  for (let mirror = 0; mirror < 2; mirror++) {
    for (let rotation = 0; rotation < 4; rotation++) {
      // Apply transformations
      let shape = [...baseShape];
      let ports = [...basePorts];

      // Apply mirror
      if (mirror === 1) {
        shape = mirrorShape(shape);
        ports = ports.map(mirrorPort);
      }

      // Apply rotations
      for (let r = 0; r < rotation; r++) {
        shape = rotateShape(shape);
        ports = ports.map(rotatePort);
      }

      // Normalize shape (shift so min row/col >= 0)
      const minRow = Math.min(...shape.map(p => p.row));
      const minCol = Math.min(...shape.map(p => p.col));
      const normalizedShape = shape.map(p => ({
        row: p.row - minRow,
        col: p.col - minCol,
      }));
      const normalizedPorts = ports.map(p => ({
        direction: p.direction,
        row: p.row - minRow,
        col: p.col - minCol,
        type: p.type,
      }));

      // Create variant with full PortInfo
      const variant: PieceVariant = {
        id: generateVariantId(),
        type,
        shape: normalizedShape,
        ports: normalizedPorts.map(p => ({
          row: p.row,
          col: p.col,
          direction: p.direction,
          type: p.type,
          pieceId: '', // Will be set when piece is instantiated
        })),
        conveyorVariant,
      };

      variants.push(variant);
    }
  }

  // Remove duplicate variants (some pieces have symmetrical variants)
  const uniqueVariants: PieceVariant[] = [];
  const seen = new Set<string>();

  for (const v of variants) {
    const key = JSON.stringify(v.shape.sort((a, b) => a.row - b.row || a.col - b.col)) +
      JSON.stringify(v.ports.sort((a, b) => a.row - b.row || a.col - b.col));
    if (!seen.has(key)) {
      seen.add(key);
      uniqueVariants.push(v);
    }
  }

  return uniqueVariants;
}

/**
 * Base piece definitions
 */

// Apple Source: 2x2, all outer sides are output ports
const SOURCE_BASE_SHAPE: Point[] = [
  { row: 0, col: 0 },
  { row: 0, col: 1 },
  { row: 1, col: 0 },
  { row: 1, col: 1 },
];

const SOURCE_BASE_PORTS = [
  // Top edge of top row
  { direction: 'north' as Direction, row: 0, col: 0, type: 'output' as const },
  { direction: 'north' as Direction, row: 0, col: 1, type: 'output' as const },
  // Bottom edge of bottom row
  { direction: 'south' as Direction, row: 1, col: 0, type: 'output' as const },
  { direction: 'south' as Direction, row: 1, col: 1, type: 'output' as const },
  // Left edge of left column
  { direction: 'west' as Direction, row: 0, col: 0, type: 'output' as const },
  { direction: 'west' as Direction, row: 1, col: 0, type: 'output' as const },
  // Right edge of right column
  { direction: 'east' as Direction, row: 0, col: 1, type: 'output' as const },
  { direction: 'east' as Direction, row: 1, col: 1, type: 'output' as const },
];

// Conveyor 1x1 horizontal: input left, output right
const CONVEYOR_1X1_SHAPE: Point[] = [{ row: 0, col: 0 }];
const CONVEYOR_1X1_PORTS = [
  { direction: 'west' as Direction, row: 0, col: 0, type: 'input' as const },
  { direction: 'east' as Direction, row: 0, col: 0, type: 'output' as const },
];

// Conveyor 1x2 horizontal: input left of left cell, output right of right cell
const CONVEYOR_1X2_SHAPE: Point[] = [
  { row: 0, col: 0 },
  { row: 0, col: 1 },
];
const CONVEYOR_1X2_PORTS = [
  { direction: 'west' as Direction, row: 0, col: 0, type: 'input' as const },
  { direction: 'east' as Direction, row: 0, col: 1, type: 'output' as const },
];

// Conveyor Corner: 2x2, 3 cells, turns right/left
// Shape: three cells forming a corner
const CONVEYOR_CORNER_SHAPE: Point[] = [
  { row: 0, col: 0 },
  { row: 0, col: 1 },
  { row: 1, col: 1 },
];
// Input at (0,0) west, output at (1,1) south (turning right)
const CONVEYOR_CORNER_PORTS = [
  { direction: 'west' as Direction, row: 0, col: 0, type: 'input' as const },
  { direction: 'south' as Direction, row: 1, col: 1, type: 'output' as const },
];

// Processor: 3x1 vertical, central cell has input left, output right
const PROCESSOR_SHAPE: Point[] = [
  { row: 0, col: 0 },
  { row: 1, col: 0 },
  { row: 2, col: 0 },
];
const PROCESSOR_PORTS = [
  { direction: 'west' as Direction, row: 1, col: 0, type: 'input' as const },
  { direction: 'east' as Direction, row: 1, col: 0, type: 'output' as const },
];

// Container: 2x3, all outer sides are ports (input or output)
const CONTAINER_SHAPE: Point[] = [
  { row: 0, col: 0 }, { row: 0, col: 1 }, { row: 0, col: 2 },
  { row: 1, col: 0 }, { row: 1, col: 1 }, { row: 1, col: 2 },
];
const CONTAINER_PORTS = [
  // Top edge
  { direction: 'north' as Direction, row: 0, col: 0, type: 'input' as const },
  { direction: 'north' as Direction, row: 0, col: 1, type: 'input' as const },
  { direction: 'north' as Direction, row: 0, col: 2, type: 'input' as const },
  // Bottom edge
  { direction: 'south' as Direction, row: 1, col: 0, type: 'output' as const },
  { direction: 'south' as Direction, row: 1, col: 1, type: 'output' as const },
  { direction: 'south' as Direction, row: 1, col: 2, type: 'output' as const },
  // Left edge
  { direction: 'west' as Direction, row: 0, col: 0, type: 'input' as const },
  { direction: 'west' as Direction, row: 1, col: 0, type: 'input' as const },
  // Right edge
  { direction: 'east' as Direction, row: 0, col: 2, type: 'output' as const },
  { direction: 'east' as Direction, row: 1, col: 2, type: 'output' as const },
];

/**
 * All piece variant definitions
 */
export const PIECE_VARIANTS: Record<PieceType, PieceVariant[]> = {
  source: generateVariants('source', SOURCE_BASE_SHAPE, SOURCE_BASE_PORTS),
  conveyor: [
    ...generateVariants('conveyor', CONVEYOR_1X1_SHAPE, CONVEYOR_1X1_PORTS, '1x1'),
    ...generateVariants('conveyor', CONVEYOR_1X2_SHAPE, CONVEYOR_1X2_PORTS, '1x2'),
    ...generateVariants('conveyor', CONVEYOR_CORNER_SHAPE, CONVEYOR_CORNER_PORTS, 'corner'),
  ],
  processor: generateVariants('processor', PROCESSOR_SHAPE, PROCESSOR_PORTS),
  container: generateVariants('container', CONTAINER_SHAPE, CONTAINER_PORTS),
};

/**
 * Creates a new piece instance from a variant
 */
export function createPiece(
  variant: PieceVariant,
  position: Point,
  type: PieceType,
  conveyorVariant?: ConveyorVariant
): import('./types.js').Piece {
  const now = Date.now();
  const pieceId = `${type}_${now}_${pieceIdCounter++}`;

  // Update port pieceIds
  const ports = variant.ports.map(p => ({ ...p, pieceId }));

  return {
    id: pieceId,
    type,
    variant: { ...variant, ports },
    position,
    resources: type === 'source' ? { apple: 8 } : {},
    connectedPorts: new Map(),
    active: true,
    processorInput: null,
    processorOutput: null,
    processorProgress: 0,
    containerType: null,
    containerStorage: [],
  };
}

/**
 * Gets a random variant for a piece type
 */
export function getRandomVariant(type: PieceType, prng: import('./types.js').SeededRandom): PieceVariant {
  const variants = PIECE_VARIANTS[type];
  return variants[prng.nextInt(0, variants.length - 1)];
}

/**
 * Gets all variants for a piece type (for shop generation)
 */
export function getAllVariants(type: PieceType): PieceVariant[] {
  return [...PIECE_VARIANTS[type]];
}

/**
 * Checks if a piece is a source piece
 */
export function isSourcePiece(piece: import('./types.js').Piece): boolean {
  return piece.type === 'source';
}

/**
 * Checks if a piece is a conveyor piece
 */
export function isConveyorPiece(piece: import('./types.js').Piece): boolean {
  return piece.type === 'conveyor';
}

/**
 * Checks if a piece is a processor piece
 */
export function isProcessorPiece(piece: import('./types.js').Piece): boolean {
  return piece.type === 'processor';
}

/**
 * Checks if a piece is a container piece
 */
export function isContainerPiece(piece: import('./types.js').Piece): boolean {
  return piece.type === 'container';
}