/**
 * Renders apple and apple slice resources.
 * Whole apples are red circles, apple slices are white semicircles with red edge.
 */

import { Resource, ResourceType, Point } from '../core/types.js';
import { drawSprite, getSprite, type Sprite, type AssetManager } from './sprites.js';
import { gridToScreen } from './render-field.js';

export interface RenderResourceConfig {
  /** Size of resource as fraction of cell */
  resourceSizeFraction: number;
  /** Animation speed */
  animationSpeed: number;
}

const DEFAULT_RESOURCE_CONFIG: RenderResourceConfig = {
  resourceSizeFraction: 0.6,
  animationSpeed: 1.0,
};

/**
 * Renders all resources on the field
 */
export function renderResources(
  ctx: CanvasRenderingContext2D,
  resources: Resource[],
  cellSize: number,
  offsetX: number,
  offsetY: number,
  config: Partial<RenderResourceConfig> = {},
  spriteManager?: AssetManager
): void {
  const cfg = { ...DEFAULT_RESOURCE_CONFIG, ...config };
  const resourceSize = cellSize * cfg.resourceSizeFraction;

  for (const resource of resources) {
    renderResource(
      ctx,
      resource,
      cellSize,
      offsetX,
      offsetY,
      resourceSize,
      cfg,
      spriteManager
    );
  }
}

/**
 * Renders a single resource at its current position
 */
export function renderResource(
  ctx: CanvasRenderingContext2D,
  resource: Resource,
  cellSize: number,
  offsetX: number,
  offsetY: number,
  resourceSize: number,
  config: RenderResourceConfig,
  spriteManager?: AssetManager
): void {
  const { x, y } = gridToScreen(resource.currentCell, cellSize, offsetX, offsetY);

  // Get sprite
  const sprite = spriteManager ? getSprite(spriteManager, resource.type) : null;

  if (sprite) {
    drawSprite(ctx, sprite, x - resourceSize / 2, y - resourceSize / 2, resourceSize, resourceSize);
  } else {
    // Draw placeholder based on type
    if (resource.type === 'apple') {
      drawApplePlaceholder(ctx, x, y, resourceSize);
    } else {
      drawAppleSlicePlaceholder(ctx, x, y, resourceSize);
    }
  }
}

/**
 * Draws an apple placeholder (red circle)
 */
export function drawApplePlaceholder(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  size: number
): void {
  const radius = size / 2;

  // Main apple body
  ctx.fillStyle = '#e74c3c';
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();

  // Highlight
  ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
  ctx.beginPath();
  ctx.arc(x - radius * 0.3, y - radius * 0.3, radius * 0.3, 0, Math.PI * 2);
  ctx.fill();

  // Stem
  ctx.strokeStyle = '#8b4513';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x, y - radius);
  ctx.lineTo(x, y - radius * 1.2);
  ctx.stroke();

  // Leaf
  ctx.fillStyle = '#27ae60';
  ctx.beginPath();
  ctx.ellipse(x + radius * 0.2, y - radius * 1.1, radius * 0.3, radius * 0.15, Math.PI / 4, 0, Math.PI * 2);
  ctx.fill();
}

/**
 * Draws an apple slice placeholder (white semicircle with red edge)
 */
export function drawAppleSlicePlaceholder(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  size: number
): void {
  const radius = size / 2;

  // White semicircle
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(x, y, radius, -Math.PI / 2, Math.PI / 2);
  ctx.fill();

  // Red peel edge
  ctx.strokeStyle = '#e74c3c';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(x, y, radius, -Math.PI / 2, Math.PI / 2);
  ctx.stroke();

  // Flat edge
  ctx.strokeStyle = '#f5f5f5';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x - radius, y);
  ctx.lineTo(x + radius, y);
  ctx.stroke();

  // Seeds/details
  ctx.fillStyle = '#8b4513';
  ctx.beginPath();
  ctx.ellipse(x - radius * 0.3, y, radius * 0.1, radius * 0.2, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(x + radius * 0.3, y, radius * 0.1, radius * 0.2, 0, 0, Math.PI * 2);
  ctx.fill();
}

/**
 * Renders resource movement animation between cells
 */
export function renderResourceAnimation(
  ctx: CanvasRenderingContext2D,
  resource: Resource,
  fromCell: Point,
  toCell: Point,
  progress: number, // 0 to 1
  cellSize: number,
  offsetX: number,
  offsetY: number,
  resourceSize: number,
  config: RenderResourceConfig,
  spriteManager?: AssetManager
): void {
  // Interpolate position
  const fromScreen = gridToScreen(fromCell, cellSize, offsetX, offsetY);
  const toScreen = gridToScreen(toCell, cellSize, offsetX, offsetY);

  const x = fromScreen.x + (toScreen.x - fromScreen.x) * progress;
  const y = fromScreen.y + (toScreen.y - fromScreen.y) * progress;

  // Get sprite
  const sprite = spriteManager ? getSprite(spriteManager, resource.type) : null;

  if (sprite) {
    drawSprite(ctx, sprite, x - resourceSize / 2, y - resourceSize / 2, resourceSize, resourceSize);
  } else {
    // Draw placeholder
    if (resource.type === 'apple') {
      drawApplePlaceholder(ctx, x, y, resourceSize);
    } else {
      drawAppleSlicePlaceholder(ctx, x, y, resourceSize);
    }
  }
}

/**
 * Renders resources inside a container piece
 */
export function renderContainerResources(
  ctx: CanvasRenderingContext2D,
  resources: Resource[],
  containerPosition: Point,
  containerShape: Point[],
  cellSize: number,
  offsetX: number,
  offsetY: number,
  resourceSize: number,
  config: RenderResourceConfig,
  spriteManager?: AssetManager
): void {
  // Sort resources into cells (fill from top-left)
  const sortedResources = [...resources].sort((a, b) => {
    const aRow = a.currentCell.row - containerPosition.row;
    const aCol = a.currentCell.col - containerPosition.col;
    const bRow = b.currentCell.row - containerPosition.row;
    const bCol = b.currentCell.col - containerPosition.col;
    if (aRow !== bRow) return aRow - bRow;
    return aCol - bCol;
  });

  for (const resource of sortedResources) {
    const { x, y } = gridToScreen(resource.currentCell, cellSize, offsetX, offsetY);
    const sprite = spriteManager ? getSprite(spriteManager, resource.type) : null;

    if (sprite) {
      drawSprite(ctx, sprite, x - resourceSize / 2, y - resourceSize / 2, resourceSize, resourceSize);
    } else {
      if (resource.type === 'apple') {
        drawApplePlaceholder(ctx, x, y, resourceSize);
      } else {
        drawAppleSlicePlaceholder(ctx, x, y, resourceSize);
      }
    }
  }
}

/**
 * Renders a queue of resources on a conveyor
 */
export function renderConveyorQueue(
  ctx: CanvasRenderingContext2D,
  resources: Resource[],
  conveyorPosition: Point,
  conveyorShape: Point[],
  cellSize: number,
  offsetX: number,
  offsetY: number,
  resourceSize: number,
  config: RenderResourceConfig,
  spriteManager?: AssetManager
): void {
  // Resources are in sequential order on conveyor cells
  for (const resource of resources) {
    const { x, y } = gridToScreen(resource.currentCell, cellSize, offsetX, offsetY);
    const sprite = spriteManager ? getSprite(spriteManager, resource.type) : null;

    if (sprite) {
      drawSprite(ctx, sprite, x - resourceSize / 2, y - resourceSize / 2, resourceSize, resourceSize);
    } else {
      if (resource.type === 'apple') {
        drawApplePlaceholder(ctx, x, y, resourceSize);
      } else {
        drawAppleSlicePlaceholder(ctx, x, y, resourceSize);
      }
    }
  }
}

/**
 * Gets the color for a resource type
 */
export function getResourceColor(type: ResourceType): string {
  switch (type) {
    case 'apple': return '#e74c3c';
    case 'apple_slice': return '#ffffff';
  }
}