/**
 * Field grid management - 12x12 play area with cell occupancy tracking.
 */

import { GRID_SIZE, Field, Cell, Point, Piece, Resource, PieceVariant } from './types.js';

/**
 * Creates a new empty field
 */
export function createField(): Field {
  const cells: Cell[][] = [];
  for (let row = 0; row < GRID_SIZE; row++) {
    const rowCells: Cell[] = [];
    for (let col = 0; col < GRID_SIZE; col++) {
      rowCells.push({ piece: null, resource: null });
    }
    cells.push(rowCells);
  }

  return {
    width: GRID_SIZE,
    height: GRID_SIZE,
    cells,
  };
}

/**
 * Validates that coordinates are within grid bounds
 */
export function isInBounds(field: Field, point: Point): boolean {
  return (
    point.row >= 0 &&
    point.row < field.height &&
    point.col >= 0 &&
    point.col < field.width
  );
}

/**
 * Checks if a cell is on the perimeter
 */
export function isPerimeter(point: Point): boolean {
  return (
    point.row === 0 ||
    point.row === GRID_SIZE - 1 ||
    point.col === 0 ||
    point.col === GRID_SIZE - 1
  );
}

/**
 * Gets the cell at a point (with bounds checking)
 */
export function getCell(field: Field, point: Point): Cell | null {
  if (!isInBounds(field, point)) return null;
  return field.cells[point.row][point.col];
}

/**
 * Checks if all cells for a piece placement are empty
 */
export function canPlacePiece(field: Field, variant: PieceVariant, position: Point): boolean {
  for (const cellOffset of variant.shape) {
    const targetPoint: Point = {
      row: position.row + cellOffset.row,
      col: position.col + cellOffset.col,
    };

    if (!isInBounds(field, targetPoint)) return false;

    const cell = getCell(field, targetPoint);
    if (!cell) return false;
    if (cell.piece !== null) return false;
  }
  return true;
}

/**
 * Places a piece on the field
 */
export function placePiece(field: Field, piece: Piece): boolean {
  for (const cellOffset of piece.variant.shape) {
    const targetPoint: Point = {
      row: piece.position.row + cellOffset.row,
      col: piece.position.col + cellOffset.col,
    };

    const cell = getCell(field, targetPoint);
    if (!cell) return false;
    if (cell.piece !== null) return false;
  }

  // Place the piece in all occupied cells
  for (const cellOffset of piece.variant.shape) {
    const targetPoint: Point = {
      row: piece.position.row + cellOffset.row,
      col: piece.position.col + cellOffset.col,
    };

    const cell = getCell(field, targetPoint);
    if (cell) cell.piece = piece;
  }

  return true;
}

/**
 * Removes a piece from the field
 */
export function removePiece(field: Field, piece: Piece): boolean {
  for (let row = 0; row < field.height; row++) {
    for (let col = 0; col < field.width; col++) {
      const cell = field.cells[row][col];
      if (cell.piece === piece) {
        cell.piece = null;
        cell.resource = null; // Also remove resources on the piece
      }
    }
  }
  return true;
}

/**
 * Moves a piece to a new position (removes resources on it)
 */
export function movePiece(field: Field, piece: Piece, newPosition: Point, variant: PieceVariant): boolean {
  if (!canPlacePiece(field, variant, newPosition)) return false;

  // Clear resources on the piece and all occupied cells
  for (const cellOffset of piece.variant.shape) {
    const oldPoint: Point = {
      row: piece.position.row + cellOffset.row,
      col: piece.position.col + cellOffset.col,
    };
    const cell = getCell(field, oldPoint);
    if (cell) {
      cell.piece = null;
      cell.resource = null;
    }
  }

  // Clear resources on the piece itself
  piece.resources = {};
  piece.connectedPorts.clear();
  piece.processorInput = null;
  piece.processorOutput = null;
  piece.containerStorage = [];

  // Update piece position
  piece.position = newPosition;
  piece.variant = variant;

  // Place at new location
  for (const cellOffset of variant.shape) {
    const targetPoint: Point = {
      row: newPosition.row + cellOffset.row,
      col: newPosition.col + cellOffset.col,
    };
    const cell = getCell(field, targetPoint);
    if (cell) cell.piece = piece;
  }

  return true;
}

/**
 * Gets the adjacent cell in a direction
 */
export function getAdjacentCell(point: Point, direction: 'north' | 'south' | 'east' | 'west'): Point {
  switch (direction) {
    case 'north': return { row: point.row - 1, col: point.col };
    case 'south': return { row: point.row + 1, col: point.col };
    case 'east': return { row: point.row, col: point.col + 1 };
    case 'west': return { row: point.row, col: point.col - 1 };
  }
}

/**
 * Gets all perimeter cells
 */
export function getPerimeterCells(): Point[] {
  const cells: Point[] = [];

  // Top and bottom rows
  for (let col = 0; col < GRID_SIZE; col++) {
    cells.push({ row: 0, col });
    cells.push({ row: GRID_SIZE - 1, col });
  }

  // Left and right columns (excluding corners already added)
  for (let row = 1; row < GRID_SIZE - 1; row++) {
    cells.push({ row, col: 0 });
    cells.push({ row, col: GRID_SIZE - 1 });
  }

  return cells;
}

/**
 * Finds a piece by ID
 */
export function findPiece(field: Field, pieceId: string): Piece | null {
  for (let row = 0; row < field.height; row++) {
    for (let col = 0; col < field.width; col++) {
      if (field.cells[row][col].piece?.id === pieceId) {
        return field.cells[row][col].piece;
      }
    }
  }
  return null;
}

/**
 * Gets all pieces on the field
 */
export function getAllPieces(field: Field): Piece[] {
  const seen = new Set<string>();
  const pieces: Piece[] = [];

  for (let row = 0; row < field.height; row++) {
    for (let col = 0; col < field.width; col++) {
      const piece = field.cells[row][col].piece;
      if (piece && !seen.has(piece.id)) {
        seen.add(piece.id);
        pieces.push(piece);
      }
    }
  }

  return pieces;
}

/**
 * Gets all resources on the field
 */
export function getAllResources(field: Field): Resource[] {
  const resources: Resource[] = [];

  for (let row = 0; row < field.height; row++) {
    for (let col = 0; col < field.width; col++) {
      const resource = field.cells[row][col].resource;
      if (resource) {
        resources.push(resource);
      }
    }
  }

  return resources;
}