/**
 * Core simulation engine with fixed 60Hz timestep.
 * Orchestrates all game systems for deterministic replay.
 */

import {
  GameState,
  SimulationTickResult,
  UserAction,
  SeededRandom,
  Field,
  Piece,
  Connection,
} from './types.js';
import { createSeededRandom, DEFAULT_SEED } from './prng.js';
import { createField } from './grid.js';
import { getAllPieces, findPiece } from './grid.js';
import { updateConnections } from './connections.js';
import { processResourceFlow } from './resource-flow.js';
import { tickShop } from './shop.js';
import { tickOrders } from './orders.js';
import { TICK_RATE_MS } from './types.js';

export class SimulationEngine {
  private state: GameState;
  private seed: number;
  private prng: SeededRandom;
  private pendingActions: UserAction[] = [];

  constructor(initialState: Partial<GameState> = {}, seed: number = Date.now()) {
    this.seed = seed;
    this.prng = createSeededRandom(seed);

    // Initialize state
    this.state = this.initializeState(initialState);
  }

  private initializeState(partial: Partial<GameState>): GameState {
    return {
      field: partial.field || createField(),
      resources: {
        apples: partial.resources?.apples ?? 15,
        appleSlices: partial.resources?.appleSlices ?? 0,
      },
      orders: {
        current: partial.orders?.current ?? this.generateInitialOrder(),
        completed: partial.orders?.completed ?? 0,
      },
      shop: partial.shop ?? this.initializeShop(),
      timestamp: Date.now(),
      tickCount: 0,
      seed: this.seed,
    };
  }

  private initializeShop() {
    return {
      freeSlots: Array(3).fill(null).map(() => ({ piece: null })),
      conveyorSlot: { piece: null },
      allTypesSlot: { piece: null },
      rerollCooldown: 0,
      firstCycle: true,
    };
  }

  private generateInitialOrder() {
    const quantity = 20 + Math.floor(this.prng.nextInt(0, 10));
    const type: 'apple' | 'apple_slice' = this.prng.nextInt(0, 1) === 0 ? 'apple' : 'apple_slice';
    const id = Date.now().toString();

    return {
      id,
      requiredResourceType: type,
      requiredQuantity: quantity,
      generatedAt: 0,
      completedAt: null,
      buttonHighlighted: this.state.resources[type] >= quantity,
    };
  }

  /**
   * Process a single simulation tick (1/60 second)
   */
  tick(): SimulationTickResult {
    // Apply any pending actions first
    this.applyPendingActions();

    const startTime = performance.now();
    const movedResources: any[] = [];
    const blockages: any[] = [];
    const pieceActivities: any[] = [];

    // Update shop (decrements cooldown)
    this.state.shop.rerollCooldown = Math.max(0, this.state.shop.rerollCooldown - 1);

    // Get pieces and connections
    const pieces = getAllPieces(this.state.field);
    let connections = updateConnections(this.state.field);

    // Process resource flow
    const flowResult = processResourceFlow(
      pieces,
      connections,
      movedResources
    );
    blockages.push(...flowResult.blockages);
    pieceActivities.push(...flowResult.activities);

    // Process shop (refill pieces)
    this.refillShop();

    // Process orders (check completion)
    tickOrders(this.state);

    // Update state
    this.state.tickCount++;
    this.state.timestamp = Date.now();

    return {
      newState: this.state,
      movedResources,
      blockages,
      pieceActivities,
    };
  }

  private refillShop(): void {
    // If all free slots are placed, refill them
    const allPlaced = this.state.shop.freeSlots.every(slot => slot.piece !== null);
    if (allPlaced) {
      // Generate new pieces
      // Note: Actual piece generation logic will be in shop.ts
      this.state.shop.freeSlots = [
        { piece: this.prng.nextInt(0, 1) === 0 ? 'apple-source-variant-1' : 'conveyor-1x1-variant-1' },
        { piece: 'apple-source-variant-1' }, // Guarantee Apple Source in first cycle
        { piece: 'empty' },
      ];
      if (this.state.shop.firstCycle) {
        // Replace a random slot with Apple Source for first cycle
        const appleSourceSlot = this.prng.nextInt(0, 2);
        this.state.shop.freeSlots[appleSourceSlot] = { piece: 'apple-source-variant-1' };
        this.state.shop.firstCycle = false;
      }
    }
  }

  private applyPendingActions(): void {
    // Actions are applied at the start of the next tick
    // This is a placeholder for action processing
    while (this.pendingActions.length > 0) {
      const action = this.pendingActions.shift();
      if (action) {
        this.applyAction(action);
      }
    }
  }

  /**
   * Apply a user action to the simulation
   */
  applyAction(action: UserAction): GameState | null {
    switch (action.type) {
      case 'place_piece':
        return this.placePiece(action);
      case 'move_piece':
        return this.movePiece(action);
      case 'click_piece':
        return this.clickPiece(action);
      case 'pause_piece':
        return this.togglePause(action);
      case 'reroll_slot':
        return this.rerollSlot(action);
      case 'complete_order':
        return this.completeOrder();
      case 'restart_game':
        return this.restart();
      default:
        return null;
    }
  }

  private placePiece(action: UserAction): GameState | null {
    // Implementation for placing pieces
    // Will be fully implemented after all helper methods
    return this.state;
  }

  private movePiece(action: UserAction): GameState | null {
    // Implementation for moving pieces
    return this.state;
  }

  private clickPiece(action: UserAction): GameState | null {
    // Implementation for clicking pieces
    return this.state;
  }

  private togglePause(action: UserAction): GameState | null {
    // Implementation for pause/resume
    return this.state;
  }

  private rerollSlot(action: UserAction): GameState | null {
    // Implementation for shop rerolls
    return this.state;
  }

  private completeOrder(): GameState | null {
    const order = this.state.orders.current;
    const { apples, appleSlices } = this.state.resources;
    const required = order.requiredResourceType;

    if (this.state.resources[required] >= order.requiredQuantity) {
      this.state.resources[required] -= order.requiredQuantity;
      this.state.orders.completed++;
      order.completedAt = this.state.timestamp;

      // Check victory
      if (this.state.orders.completed >= 5) {
        // Victory achieved
        // TODO: Show victory screen
      }

      // Generate new order
      this.state.orders.current = this.generateInitialOrder();
      this.state.orders.current.buttonHighlighted =
        this.state.resources[order.requiredResourceType] >=
        this.state.orders.current.requiredQuantity;
    }

    return this.state;
  }

  private restart(): GameState {
    this.state = this.initializeState({});
    return this.state;
  }

  /**
   * Get current game state
   */
  getState(): GameState {
    return { ...this.state };
  }

  /**
   * Serialize game state for save/replay
   */
  serialize(): string {
    return JSON.stringify({
      field: this.state.field,
      resources: this.state.resources,
      orders: this.state.orders,
      shop: this.state.shop,
      tickCount: this.state.tickCount,
      seed: this.seed,
    });
  }

  /**
   * Create engine from serialized state
   */
  static deserialize(serialized: string): SimulationEngine {
    const data = JSON.parse(serialized);
    const engine = new SimulationEngine(data, data.seed);
    engine.state = data;
    return engine;
  }
}

/**
 * Create a new simulation engine
 */
export function createSimulation(initialState?: Partial<GameState>, seed?: number): SimulationEngine {
  return new SimulationEngine(initialState, seed);
}