/**
 * Connection detection between pieces via port matching.
 * Detects when output ports connect to input ports.
 */

import { Field, Piece, PortInfo, Connection, Point, Direction } from './types.js';
import { getAdjacentCell, isInBounds, getCell, getAllPieces } from './grid.js';
import { isPerimeter } from './grid.js';

let connectionIdCounter = 0;

function generateConnectionId(): string {
  return `conn_${++connectionIdCounter}`;
}

/**
 * Gets the direction from one cell to an adjacent cell
 */
function getDirection(from: Point, to: Point): Direction {
  if (to.row < from.row) return 'north';
  if (to.row > from.row) return 'south';
  if (to.col < from.col) return 'west';
  return 'east';
}

/**
 * Gets the opposite direction
 */
function getOppositeDirection(dir: Direction): Direction {
  switch (dir) {
    case 'north': return 'south';
    case 'south': return 'north';
    case 'east': return 'west';
    case 'west': return 'east';
  }
}

/**
 * Checks if an output port of one piece faces an input port of another piece
 */
function arePortsMatching(output: PortInfo, input: PortInfo, piece: Piece): boolean {
  const outputPoint = { row: piece.position.row + output.row, col: piece.position.col + output.col };
  const adjacentPoint = getAdjacentCell(outputPoint, output.direction);
  const oppositeDir = getOppositeDirection(output.direction);

  // The input port should face the opposite direction
  return input.direction === oppositeDir;
}

/**
 * Detects all connections on the field
 */
export function detectConnections(field: Field): Connection[] {
  const connections: Connection[] = [];
  const pieces = getAllPieces(field);
  const seenConnections = new Set<string>();

  for (const piece of pieces) {
    for (const port of piece.variant.ports) {
      const outputPoint: Point = {
        row: piece.position.row + port.row,
        col: piece.position.col + port.col,
      };

      if (port.type === 'output') {
        // Check connection to adjacent piece's input port
        const adjacentPoint = getAdjacentCell(outputPoint, port.direction);

        if (isInBounds(field, adjacentPoint)) {
          const adjacentCell = getCell(field, adjacentPoint);
          const adjacentPiece = adjacentCell?.piece;

          if (adjacentPiece && adjacentPiece.id !== piece.id) {
            // Find matching input port on adjacent piece
            const oppositeDir = getOppositeDirection(port.direction);

            for (const adjPort of adjacentPiece.variant.ports) {
              if (
                adjPort.type === 'input' &&
                adjPort.row === port.row && adjPort.col === port.col && adjPort.direction === oppositeDir
              ) {
                // Verify this is actually an adjacent cell on the same relative position
                const adjPortPoint = {
                  row: adjacentPiece.position.row + adjPort.row,
                  col: adjacentPiece.position.col + adjPort.col,
                };

                if (adjPortPoint.row === outputPoint.row && adjPortPoint.col === outputPoint.col && adjPortPoint.row === adjacentPoint.row && adjPortPoint.col === adjacentPoint.col) {
                  const connKey = `${piece.id}-${port.row},${port.col}-${adjacentPiece.id}-${adjPort.row},${adjPort.col}`;
                  if (!seenConnections.has(connKey)) {
                    seenConnections.add(connKey);
                    connections.push({
                      id: generateConnectionId(),
                      sourcePieceId: piece.id,
                      sourcePort: { ...port, pieceId: piece.id },
                      targetPieceId: adjacentPiece.id,
                      targetPort: { ...adjPort, pieceId: adjacentPiece.id },
                      active: true,
                      resourceQueue: [],
                    });
                  }
                }
              }
            }
          }
        }

        // Check connection to field perimeter
        if (isPerimeter({ row: piece.position.row + port.row, col: piece.position.col + port.col })) {
          const connKey = `${piece.id}-${port.row},${port.col}-perimeter`;
          if (!seenConnections.has(connKey)) {
            seenConnections.add(connKey);
            connections.push({
              id: generateConnectionId(),
              sourcePieceId: piece.id,
              sourcePort: { ...port, pieceId: piece.id },
              targetPieceId: 'perimeter',
              targetPort: { ...port, pieceId: 'perimeter' },
              active: true,
              resourceQueue: [],
            });
          }
        }
      }

      if (port.type === 'input') {
        // Find output port from adjacent piece that connects to this input
        const inputPoint: Point = {
          row: piece.position.row + port.row,
          col: piece.position.col + port.col,
        };

        const adjacentPoint = getAdjacentCell(inputPoint, port.direction);
        const oppositeDir = getOppositeDirection(port.direction);

        if (isInBounds(field, adjacentPoint)) {
          const adjacentCell = getCell(field, adjacentPoint);
          const adjacentPiece = adjacentCell?.piece;

          if (adjacentPiece && adjacentPiece.id !== piece.id) {
            for (const adjPort of adjacentPiece.variant.ports) {
              if (
                adjPort.type === 'output' &&
                adjPort.direction === oppositeDir
              ) {
                const adjPortPoint = {
                  row: adjacentPiece.position.row + adjPort.row,
                  col: adjacentPiece.position.col + adjPort.col,
                };

                if (adjPortPoint.row === inputPoint.row && adjPortPoint.col === inputPoint.col) {
                  const connKey = `${adjacentPiece.id}-${adjPort.row},${adjPort.col}-${piece.id}-${port.row},${port.col}`;
                  if (!seenConnections.has(connKey)) {
                    seenConnections.add(connKey);
                    connections.push({
                      id: generateConnectionId(),
                      sourcePieceId: adjacentPiece.id,
                      sourcePort: { ...adjPort, pieceId: adjacentPiece.id },
                      targetPieceId: piece.id,
                      targetPort: { ...port, pieceId: piece.id },
                      active: true,
                      resourceQueue: [],
                    });
                  }
                }
              }
            }
          }
        }

        // Special: input port on a perimeter cell connects to field output (from perimeter)
        if (isPerimeter(inputPoint)) {
          // Perimeter acts as input port (receiver) — connections from pieces to perimeter
          // This is already handled when checking output ports above
        }
      }
    }
  }

  return connections;
}

/**
 * Updates all connections on the field and returns active ones
 */
export function updateConnections(field: Field): Connection[] {
  const newConnections = detectConnections(field);

  // Update pieces with their connections
  const pieces = getAllPieces(field);
  for (const piece of pieces) {
    piece.connectedPorts.clear();
  }

  for (const conn of newConnections) {
    const sourcePiece = pieces.find(p => p.id === conn.sourcePieceId);
    const targetPiece = pieces.find(p => p.id === conn.targetPieceId);

    if (sourcePiece) {
      sourcePiece.connectedPorts.set(conn.id, conn);
    }
    if (targetPiece) {
      targetPiece.connectedPorts.set(conn.id, conn);
    }
  }

  return newConnections;
}

/**
 * Checks if a connection is valid (ports match input/output correctly)
 */
export function isValidConnection(sourcePort: PortInfo, targetPort: PortInfo): boolean {
  if (sourcePort.type !== 'output' || targetPort.type !== 'input') return false;

  const oppositeDir = getOppositeDirection(sourcePort.direction);
  return targetPort.direction === oppositeDir;
}

/**
 * Gets all connections for a specific piece
 */
export function getPieceConnections(piece: Piece): Connection[] {
  return Array.from(piece.connectedPorts.values());
}

/**
 * Gets all output connections from a piece (resources leaving it)
 */
export function getOutputConnections(piece: Piece, connections: Connection[]): Connection[] {
  return connections.filter(c => c.sourcePieceId === piece.id && c.active);
}

/**
 * Gets all input connections to a piece (resources entering it)
 */
export function getInputConnections(piece: Piece, connections: Connection[]): Connection[] {
  return connections.filter(c => c.targetPieceId === piece.id && c.active);
}

/**
 * Gets connections that lead to the field perimeter
 */
export function getPerimeterConnections(piece: Piece, connections: Connection[]): Connection[] {
  return connections.filter(c => c.sourcePieceId === piece.id && c.targetPieceId === 'perimeter' && c.active);
}

/**
 * Checks if a piece can connect to another piece
 */
export function canConnect(pieceA: Piece, pieceB: Piece): boolean {
  const connections = detectConnections({
    width: 12,
    height: 12,
    cells: Array.from({ length: 12 }, () =>
      Array.from({ length: 12 }, () => ({ piece: null, resource: null }))
    ),
  });
  // Simplified: check if any outputs/inputs face each other
  // This is handled in detectConnections above
  return connections.length > 0;
}

/**
 * Resolves all chains (sequences of connected pieces from source to receiver)
 */
export function resolveChains(field: Field, connections: Connection[]): Connection[][] {
  const chains: Connection[][] = [];
  const visited = new Set<string>();

  for (const conn of connections) {
    if (visited.has(conn.id)) continue;

    const chain: Connection[] = [conn];
    visited.add(conn.id);

    // Follow chain through connected pieces
    let currentTarget = conn.targetPieceId;
    let continueChain = true;

    while (continueChain) {
      const nextConn = connections.find(
        c => c.sourcePieceId === currentTarget && !visited.has(c.id)
      );

      if (nextConn) {
        chain.push(nextConn);
        visited.add(nextConn.id);
        currentTarget = nextConn.targetPieceId;
      } else {
        continueChain = false;
      }
    }

    chains.push(chain);
  }

  return chains;
}

/**
 * Finds all available output connections from a source piece
 */
export function findSourceOutputs(piece: Piece, connections: Connection[]): Connection[] {
  if (piece.type !== 'source') return [];

  return getOutputConnections(piece, connections).filter(c => {
    // Source pieces cannot connect to perimeter (per spec rule)
    return c.targetPieceId !== 'perimeter';
  });
}

/**
 * Validates that a source piece is not connected to the field perimeter
 * Per spec: "A resource cannot move directly from a Source Piece to the outer perimeter of the field without a Conveyor Piece"
 */
export function validateSourcePerimeterConnections(piece: Piece, connections: Connection[]): boolean {
  if (piece.type !== 'source') return true;

  const perimeterConns = getPerimeterConnections(piece, connections);
  return perimeterConns.length === 0;
}
