/**
 * Renders all piece types with port arrows.
 * Each piece type has specific rendering logic.
 */

import { Piece, PieceVariant, Point } from '../core/types.js';
import { getSprite, type Sprite, type AssetManager, drawSprite, PointInRect } from './sprites.js';
import { gridToScreen } from './render-field.js';
import { PortInfo } from '../core/types.js';

export interface RenderPieceConfig {
  /** Arrow colors */
  arrowColor: string;
  /** Port size */
  portSize: number;
}

const DEFAULT_PIECE_CONFIG: RenderPieceConfig = {
  arrowColor: '#000000',
  portSize: 8,
};

/**
 * Renders a single piece on the canvas
 */
export function renderPiece(
  ctx: CanvasRenderingContext2D,
  piece: Piece,
  cellSize: number,
  offsetX: number,
  offsetY: number,
  config: Partial<RenderPieceConfig> = {},
  spriteManager?: AssetManager
): void {
  const cfg = { ...DEFAULT_PIECE_CONFIG, ...config };

  // Calculate screen position
  const { x, y } = gridToScreen(piece.position, cellSize, offsetX, offsetY);

  const { type, variant } = piece;

  // Get piece sprite
  const pieceSprite = spriteManager ? getSprite(spriteManager, getPieceSpriteName(type, variant)) : null;

  // Render based on piece type
  switch (type) {
    case 'source':
      renderSourcePiece(ctx, piece, x, y, cellSize, cfg, pieceSprite);
      break;
    case 'conveyor':
      renderConveyorPiece(ctx, piece, x, y, cellSize, cfg, pieceSprite);
      break;
    case 'processor':
      renderProcessorPiece(ctx, piece, x, y, cellSize, cfg, pieceSprite);
      break;
    case 'container':
      renderContainerPiece(ctx, piece, x, y, cellSize, cfg, pieceSprite);
      break;
  }
}

/**
 * Gets the sprite name for a piece type and variant
 */
function getPieceSpriteName(type: PieceType, variant: PieceVariant): string {
  switch (type) {
    case 'source': return 'source';
    case 'conveyor': return 'conveyor';
    case 'processor': return 'processor';
    case 'container': return 'container';
    default: return 'source';
  }
}

/**
 * Renders a Source piece (2x2 with apple count)
 */
function renderSourcePiece(
  ctx: CanvasRenderingContext2D,
  piece: Piece,
  x: number,
  y: number,
  cellSize: number,
  cfg: RenderPieceConfig,
  sprite: Sprite | null
): void {
  const dpr = window.devicePixelRatio || 1;

  // Get sprite or draw placeholder
  if (sprite) {
    // Draw sprite scaled to piece cell size
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(cellSize / sprite.width, cellSize / sprite.height);
    drawSprite(ctx, sprite, 0, 0, cellSize, cellSize);
    ctx.restore();
  } else {
    // Draw placeholder
    ctx.fillStyle = '#fadbd8';
    ctx.fillRect(x, y, cellSize * 2, cellSize * 2);

    // Brown outline
    ctx.strokeStyle = '#e74c3c';
    ctx.lineWidth = 2 * dpr;
    ctx.strokeRect(x - 1, y - 1, cellSize * 2 + 2, cellSize * 2 + 2);

    // Draw apple count in center
    const appleCount = piece.resources.apple || 8;
    ctx.fillStyle = '#e74c3c';
    ctx.font = `${cellSize * 0.6}px Arial`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(String(appleCount), x + cellSize, y + cellSize + cellSize / 4);
  }

  // Draw port arrows (output ports on all sides)
  const portSize = cellSize * 0.4;
  for (const port of variant.ports) {
    const screenPos = {
      x: x + port.row * cellSize + cellSize / 2,
      y: y + port.col * cellSize + cellSize / 2,
    };

    // Draw arrow sprite or placeholder
    if (sprite) {
      ctx.save();
      ctx.translate(screenPos.x, screenPos.y);
      ctx.rotate(Math.PI / 2);
      drawSprite(ctx, sprite, -portSize / 2, -portSize / 2, portSize, portSize);
      ctx.restore();
    } else {
      drawArrowPlaceholder(ctx, screenPos.x, screenPos.y, port.direction, portSize, cfg.arrowColor);
    }
  }
}

/**
 * Renders a Conveyor piece
 */
function renderConveyorPiece(
  ctx: CanvasRenderingContext2D,
  piece: Piece,
  x: number,
  y: number,
  cellSize: number,
  cfg: RenderPieceConfig,
  sprite: Sprite | null
): void {
  const dpr = window.devicePixelRatio || 1;

  // Get sprite or draw placeholder
  if (sprite) {
    // Draw scaled sprite
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(cellSize / sprite.width, cellSize / sprite.height);
    drawSprite(ctx, sprite, 0, 0, cellSize * 2, cellSize);
    ctx.restore();
  } else {
    // Draw placeholder
    ctx.fillStyle = '#7f8c8d';
    ctx.fillRect(x, y, cellSize * 2, cellSize);

    // Outline
    ctx.strokeStyle = '#5d6d7e';
    ctx.lineWidth = 2 * dpr;
    ctx.strokeRect(x - 1, y - 1, cellSize * 2 + 2, cellSize + 2);
  }

  // Draw port arrows
  const portSize = cellSize * 0.3;
  for (const port of variant.ports) {
    const screenPos = {
      x: x + port.row * cellSize + cellSize / 2,
      y: y + port.col * cellSize + cellSize / 2,
    };

    // Draw arrow
    if (port.type === 'output') {
      if (sprite) {
        ctx.save();
        ctx.translate(screenPos.x, screenPos.y);
        // Rotation depends on direction
        let angle = 0;
        if (port.direction === 'east') angle = -Math.PI / 2;
        else if (port.direction === 'west') angle = Math.PI / 2;
        else if (port.direction === 'north') angle = Math.PI;
        else if (port.direction === 'south') angle = 0;
        ctx.rotate(angle);
        drawSprite(ctx, sprite || null, -portSize / 2, -portSize / 2, portSize, portSize);
        ctx.restore();
      } else {
        drawArrowPlaceholder(ctx, screenPos.x, screenPos.y, port.direction, portSize, cfg.arrowColor);
      }
    }
  }
}

/**
 * Renders a Processor piece (3x1 vertical)
 */
function renderProcessorPiece(
  ctx: CanvasRenderingContext2D,
  piece: Piece,
  x: number,
  y: number,
  cellSize: number,
  cfg: RenderPieceConfig,
  sprite: Sprite | null
): void {
  const dpr = window.devicePixelRatio || 1;

  // Get sprite or draw placeholder
  if (sprite) {
    // Draw scaled sprite
    ctx.save();
    ctx.translate(x + cellSize, y + cellSize); // Center cell
    ctx.scale(cellSize / sprite.width, cellSize / sprite.height);
    drawSprite(ctx, sprite, 0, 0, cellSize, cellSize);
    ctx.restore();
  } else {
    // Draw placeholder
    ctx.fillStyle = '#2c3e50';
    ctx.fillRect(x, y, cellSize, cellSize * 3);

    // Outline
    ctx.strokeStyle = '#1a252f';
    ctx.lineWidth = 2 * dpr;
    ctx.strokeRect(x - 1, y - 1, cellSize + 2, cellSize * 3 + 2);

    // Highlight central cell
    ctx.fillStyle = '#7f8c8d';
    ctx.globalAlpha = 0.5;
    ctx.fillRect(x, y + cellSize, cellSize, cellSize);
    ctx.globalAlpha = 1.0;
  }

  // Draw port arrows (input left, output right)
  const portSize = cellSize * 0.3;
  for (const port of variant.ports) {
    const screenPos = {
      x: x + port.row * cellSize + cellSize / 2,
      y: y + port.col * cellSize + cellSize / 2,
    };

    if (port.type === 'output') {
      // Arrow pointing right
      drawArrowPlaceholder(ctx, screenPos.x + cellSize / 2, screenPos.y + cellSize / 2, 'east', portSize, cfg.arrowColor);
    } else if (port.type === 'input') {
      // Arrow pointing left
      drawArrowPlaceholder(ctx, screenPos.x - cellSize / 2, screenPos.y + cellSize / 2, 'west', portSize, cfg.arrowColor);
    }
  }
}

/**
 * Renders a Container piece (2x3)
 */
function renderContainerPiece(
  ctx: CanvasRenderingContext2D,
  piece: Piece,
  x: number,
  y: number,
  cellSize: number,
  cfg: RenderPieceConfig,
  sprite: Sprite | null
): void {
  const dpr = window.devicePixelRatio || 1;

  // Get sprite or draw placeholder
  if (sprite) {
    // Draw scaled sprite
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(cellSize / sprite.width, cellSize / sprite.height);
    drawSprite(ctx, sprite, 0, 0, cellSize * 3, cellSize * 2);
    ctx.restore();
  } else {
    // Draw placeholder
    ctx.fillStyle = '#f5e6cc';
    ctx.fillRect(x, y, cellSize * 3, cellSize * 2);

    // Brown outline
    ctx.strokeStyle = '#8b7355';
    ctx.lineWidth = 3 * dpr;
    ctx.strokeRect(x - 1, y - 1, cellSize * 3 + 2, cellSize * 2 + 2);

    // Diagonal hatching
    ctx.strokeStyle = '#a68b6b';
    ctx.lineWidth = 1 * dpr;
    for (let i = -cellSize * 2; i < cellSize * 4; i += 30) {
      ctx.beginPath();
      ctx.moveTo(x + i, y);
      ctx.lineTo(x + i + cellSize * 3, y + cellSize * 2);
      ctx.stroke();
    }
  }

  // Draw port arrows (all 6 sides)
  const portSize = cellSize * 0.25;
  for (const port of variant.ports) {
    const screenPos = {
      x: x + port.row * cellSize + cellSize / 2,
      y: y + port.col * cellSize + cellSize / 2,
    };

    drawArrowPlaceholder(ctx, screenPos.x, screenPos.y, port.direction, portSize, cfg.arrowColor);
  }
}

/**
 * Draws an arrow placeholder
 */
function drawArrowPlaceholder(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  direction: 'north' | 'south' | 'east' | 'west',
  size: number,
  color: string
): void {
  ctx.fillStyle = color;
  ctx.beginPath();

  const half = size / 2;

  switch (direction) {
    case 'north':
      ctx.moveTo(x - half, y + half);
      ctx.lineTo(x + half, y + half);
      ctx.lineTo(x, y - half);
      break;
    case 'south':
      ctx.moveTo(x - half, y - half);
      ctx.lineTo(x + half, y - half);
      ctx.lineTo(x, y + half);
      break;
    case 'east':
      ctx.moveTo(x - half, y - half);
      ctx.lineTo(x - half, y + half);
      ctx.lineTo(x + half, y);
      break;
    case 'west':
      ctx.moveTo(x + half, y - half);
      ctx.lineTo(x + half, y + half);
      ctx.lineTo(x - half, y);
      break;
  }

  ctx.closePath();
  ctx.fill();
}

