/**
 * AppleFactory Game - Main Entry Point
 * Wires core simulation + renderer + input together
 */

import { GameState, GRID_SIZE, SimulationEngine, createSimulation } from './core/index.js';
import {
  createInputManager,
  attachInputListeners,
  type InputManager,
  type PointerEvent,
} from './renderer/input.js';
import { createCanvas, resizeCanvas, clearCanvas } from './renderer/canvas.js';
import { createAssetManager, generatePlaceholders } from './renderer/sprites.js';
import { renderField, screenToGrid } from './renderer/render-field.js';
import { renderPiece, getPieceSpriteName } from './renderer/render-pieces.js';
import { renderResources } from './renderer/render-resources.js';
import { renderHUD, renderOrderButton, renderVictoryScreen, getRestartButtonBounds, getOrderButtonBounds, type HUDState } from './renderer/render-ui.js';
import { getAllPieces, getAllResources } from './core/grid.js';
import { TICK_RATE_MS } from './core/types.js';

export interface GameConfig {
  /** Canvas container element */
  container: HTMLElement;
  /** Base cell size in pixels */
  cellSize: number;
  /** HUD height */
  hudHeight: number;
}

const DEFAULT_CONFIG: Partial<GameConfig> = {
  cellSize: 48,
  hudHeight: 60,
};

/**
 * Main game class
 */
export class AppleFactoryGame {
  private engine: SimulationEngine;
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private inputManager: InputManager;
  private config: GameConfig;
  private isRunning: boolean = false;
  private lastTickTime: number = 0;
  private animationFrameId: number = 0;
  private gameWidth: number = 0;
  private gameHeight: number = 0;
  private fieldOffsetX: number = 0;
  private fieldOffsetY: number = 0;
  private spriteManager = createAssetManager();

  constructor(config: GameConfig) {
    this.config = { ...DEFAULT_CONFIG as GameConfig, ...config };

    // Initialize core simulation
    this.engine = createSimulation({}, Date.now());

    // Initialize canvas
    this.canvas = createCanvas(this.config.container);
    this.ctx = this.canvas.getContext('2d')!;

    // Initialize input
    this.inputManager = createInputManager();

    // Setup input handlers
    this.setupInputHandlers();

    // Generate placeholder sprites
    generatePlaceholders(this.spriteManager);

    // Initial resize
    this.handleResize();

    // Setup resize observer
    window.addEventListener('resize', () => this.handleResize());
  }

  /**
   * Start the game loop
   */
  start(): void {
    if (this.isRunning) return;
    this.isRunning = true;
    this.lastTickTime = performance.now();
    this.gameLoop();
  }

  /**
   * Stop the game loop
   */
  stop(): void {
    this.isRunning = false;
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
  }

  /**
   * Main game loop
   */
  private gameLoop = (): void => {
    if (!this.isRunning) return;

    const currentTime = performance.now();
    const elapsed = currentTime - this.lastTickTime;

    // Fixed timestep simulation
    if (elapsed >= TICK_RATE_MS) {
      this.engine.tick();
      this.lastTickTime = currentTime - (elapsed % TICK_RATE_MS);
    }

    // Render
    this.render();

    // Schedule next frame
    this.animationFrameId = requestAnimationFrame(this.gameLoop);
  };

  /**
   * Render the game
   */
  private render(): void {
    const state = this.engine.getState();
    const { width, height } = this.gameWidth > 0 ? { width: this.gameWidth, height: this.gameHeight } : { width: 800, height: 600 };

    // Clear canvas
    clearCanvas(this.ctx, width, height);

    // Render HUD
    const hudState: HUDState = {
      ordersCompleted: state.orders.completed,
      ordersTotal: 5,
      apples: state.resources.apples,
      appleSlices: state.resources.appleSlices,
      currentOrderId: state.orders.current.id,
      orderQuantity: state.orders.current.requiredQuantity,
      orderResourceType: state.orders.current.requiredResourceType,
      orderButtonHighlighted: state.orders.current.buttonHighlighted,
    };

    renderHUD(this.ctx, hudState, width, height);

    // Render field
    renderField(this.ctx, state.field, this.config.cellSize, this.fieldOffsetX, this.fieldOffsetY);

    // Render pieces
    const pieces = getAllPieces(state.field);
    for (const piece of pieces) {
      if (!piece.active) {
        // Draw paused overlay would go here
      }
      renderPiece(this.ctx, piece, this.config.cellSize, this.fieldOffsetX, this.fieldOffsetY, {}, this.spriteManager);
    }

    // Render resources
    const resources = getAllResources(state.field);
    renderResources(this.ctx, resources, this.config.cellSize, this.fieldOffsetX, this.fieldOffsetY, {}, this.spriteManager);

    // Render order button if highlighted
    if (hudState.orderButtonHighlighted) {
      renderOrderButton(this.ctx, hudState, width, height);
    }

    // Render victory screen if won
    if (state.orders.completed >= 5) {
      renderVictoryScreen(this.ctx, state.orders.completed, width, height);
    }
  }

  /**
   * Handle window resize
   */
  private handleResize(): void {
    const rect = this.canvas.parentElement!.getBoundingClientRect();
    this.canvas.width = rect.width * (window.devicePixelRatio || 1);
    this.canvas.height = rect.height * (window.devicePixelRatio || 1);
    this.canvas.style.width = `${rect.width}px`;
    this.canvas.style.height = `${rect.height}px`;

    // Calculate game dimensions
    this.gameWidth = rect.width;
    this.gameHeight = rect.height;

    // Calculate field offset (centered, below HUD)
    const fieldWidth = GRID_SIZE * this.config.cellSize;
    const fieldHeight = GRID_SIZE * this.config.cellSize;
    this.fieldOffsetX = (this.gameWidth - fieldWidth) / 2;
    this.fieldOffsetY = this.config.hudHeight + (this.gameHeight - this.config.hudHeight - fieldHeight) / 2;
  }

  /**
   * Setup input event handlers
   */
  private setupInputHandlers(): void {
    attachInputListeners(this.inputManager, this.canvas, (clientX, clientY) => {
      const rect = this.canvas.getBoundingClientRect();
      return {
        x: clientX - rect.left,
        y: clientY - rect.top,
      };
    });

    // Click handler for buttons
    this.inputManager.onClick = (event) => {
      this.handleClick(event);
    };

    // Drag handler for piece movement
    this.inputManager.onDragStart = (event) => {
      this.handleDragStart(event);
    };

    this.inputManager.onDragMove = (event) => {
      this.handleDragMove(event);
    };

    this.inputManager.onDragEnd = (event) => {
      this.handleDragEnd(event);
    };
  }

  /**
   * Handle click events
   */
  private handleClick(event: PointerEvent): void {
    const state = this.engine.getState();

    // Check restart button
    const restartBounds = getRestartButtonBounds(this.gameWidth, this.gameHeight);
    if (
      event.x >= restartBounds.x &&
      event.x <= restartBounds.x + restartBounds.width &&
      event.y >= restartBounds.y &&
      event.y <= restartBounds.y + restartBounds.height
    ) {
      this.engine.applyAction({
        id: Date.now().toString(),
        type: 'restart_game',
        timestamp: Date.now(),
      });
      return;
    }

    // Check order button
    const orderBounds = getOrderButtonBounds(this.gameWidth);
    if (orderBounds) {
      if (
        event.x >= orderBounds.x &&
        event.x <= orderBounds.x + orderBounds.width &&
        event.y >= orderBounds.y &&
        event.y <= orderBounds.y + orderBounds.height
      ) {
        this.engine.applyAction({
          id: Date.now().toString(),
          type: 'complete_order',
          timestamp: Date.now(),
        });
        return;
      }
    }

    // Check piece click (for pause)
    const gridPos = screenToGrid(event.x, event.y, this.config.cellSize, this.fieldOffsetX, this.fieldOffsetY);
    if (gridPos) {
      const cell = state.field.cells[gridPos.row]?.[gridPos.col];
      if (cell.piece) {
        this.engine.applyAction({
          id: Date.now().toString(),
          type: 'click_piece',
          target: cell.piece.id,
          timestamp: Date.now(),
        });
      }
    }

    // Check victory screen restart
    if (state.orders.completed >= 5) {
      this.engine.applyAction({
        id: Date.now().toString(),
        type: 'restart_game',
        timestamp: Date.now(),
      });
    }
  }

  private handleDragStart(event: PointerEvent): void {
    // TODO: Implement drag start
  }

  private handleDragMove(event: PointerEvent): void {
    // TODO: Implement drag move
  }

  private handleDragEnd(event: PointerEvent): void {
    // TODO: Implement drag end for piece placement
  }

  /**
   * Get current game state
   */
  getState(): GameState {
    return this.engine.getState();
  }

  /**
   * Get the simulation engine
   */
  getEngine(): SimulationEngine {
    return this.engine;
  }
}

/**
 * Initialize and start the game
 */
export function initGame(container: HTMLElement): AppleFactoryGame {
  const game = new AppleFactoryGame({
    container,
    cellSize: 48,
    hudHeight: 60,
  });

  game.start();
  return game;
}

// Auto-initialize when DOM is ready
function autoInit(): void {
  const container = document.getElementById('game-container');
  if (container) {
    initGame(container);
  } else if (document.readyState !== 'complete') {
    // DOM not ready yet - wait for it
    const checkReady = () => {
      const el = document.getElementById('game-container');
      if (el) {
        initGame(el);
      } else if (document.readyState !== 'complete') {
        requestAnimationFrame(checkReady);
      }
    };
    requestAnimationFrame(checkReady);
  }
}

if (typeof document !== 'undefined') {
  autoInit();
}