/**
 * Renders the HUD: order counter, resource counter, restart button.
 */

import { Point } from '../core/types.js';

export interface RenderUIConfig {
  /** Button colors */
  buttonNormalColor: string;
  buttonHighlightedColor: string;
  buttonDisabledColor: string;
  buttonTextColor: string;
  buttonHighlightedTextColor: string;
  /** Bar colors */
  barBackgroundColor: string;
  barForegroundColor: string;
  /** Font settings */
  fontSize: number;
  fontFamily: string;
}

const DEFAULT_UI_CONFIG: RenderUIConfig = {
  buttonNormalColor: '#34495e',
  buttonHighlightedColor: '#27ae60',
  buttonDisabledColor: '#5d6d7e',
  buttonTextColor: '#ffffff',
  buttonHighlightedTextColor: '#ffffff',
  barBackgroundColor: 'rgba(0, 0, 0, 0.3)',
  barForegroundColor: '#ffffff',
  fontSize: 16,
  fontFamily: 'Arial, sans-serif',
};

export interface HUDState {
  ordersCompleted: number;
  ordersTotal: number;
  apples: number;
  appleSlices: number;
  currentOrderId: string;
  orderQuantity: number;
  orderResourceType: 'apple' | 'apple_slice';
  orderButtonHighlighted: boolean;
}

/**
 * Renders the entire HUD
 */
export function renderHUD(
  ctx: CanvasRenderingContext2D,
  state: HUDState,
  canvasWidth: number,
  canvasHeight: number,
  config: Partial<RenderUIConfig> = {}
): void {
  const cfg = { ...DEFAULT_UI_CONFIG, ...config };

  // Draw semi-transparent bar at top
  ctx.fillStyle = cfg.barBackgroundColor;
  ctx.fillRect(0, 0, canvasWidth, 60);

  // Draw content
  renderOrdersCounter(ctx, state, canvasWidth, canvasHeight, cfg);
  renderResourceCounter(ctx, state, canvasWidth, canvasHeight, cfg);
  renderOrderDisplay(ctx, state, canvasWidth, canvasHeight, cfg);
  renderRestartButton(ctx, state, canvasWidth, canvasHeight, cfg);
}

/**
 * Renders order completion counter
 */
function renderOrdersCounter(
  ctx: CanvasRenderingContext2D,
  state: HUDState,
  canvasWidth: number,
  canvasHeight: number,
  cfg: RenderUIConfig
): void {
  const barHeight = 60;
  const counterX = 20;
  const counterY = barHeight / 2;

  ctx.fillStyle = cfg.buttonTextColor;
  ctx.font = `${cfg.fontSize * 1.5}px ${cfg.fontFamily}`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';

  ctx.fillText(`Orders: ${state.ordersCompleted}/${state.ordersTotal}`, counterX, counterY);
}

/**
 * Renders resource counter
 */
function renderResourceCounter(
  ctx: CanvasRenderingContext2D,
  state: HUDState,
  canvasWidth: number,
  canvasHeight: number,
  cfg: RenderUIConfig
): void {
  const barHeight = 60;
  const counterX = canvasWidth / 2;
  const counterY = barHeight / 2;

  ctx.fillStyle = cfg.buttonTextColor;
  ctx.font = `${cfg.fontSize * 1.5}px ${cfg.fontFamily}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Apples
  ctx.fillStyle = '#e74c3c';
  ctx.fillText(`🍎 ${state.apples}`, counterX, counterY);

  // Apple slices
  ctx.fillStyle = '#ffffff';
  ctx.fillText(`🍏 ${state.appleSlices}`, counterX, counterY + 30);
}

/**
 * Renders current order display with completion button
 */
function renderOrderDisplay(
  ctx: CanvasRenderingContext2D,
  state: HUDState,
  canvasWidth: number,
  canvasHeight: number,
  cfg: RenderUIConfig
): void {
  const barHeight = 60;
  const counterX = canvasWidth - 180;
  const counterY = barHeight / 2 - 20;

  ctx.fillStyle = cfg.buttonTextColor;
  ctx.font = `${cfg.fontSize * 0.9}px ${cfg.fontFamily}`;
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';

  ctx.fillText(`Current Order:`, counterX, counterY);
  ctx.fillText(`${state.orderQuantity} ${state.orderResourceType === 'apple' ? 'apples' : 'apple slices'}`, counterX, counterY + 20);
}

/**
 * Renders the restart button
 */
function renderRestartButton(
  ctx: CanvasRenderingContext2D,
  state: HUDState,
  canvasWidth: number,
  canvasHeight: number,
  cfg: RenderUIConfig
): void {
  const barHeight = 60;
  const buttonWidth = 100;
  const buttonHeight = 35;
  const buttonX = canvasWidth - 110;
  const buttonY = (barHeight - buttonHeight) / 2;

  // Button background
  ctx.fillStyle = cfg.buttonNormalColor;
  ctx.fillRect(buttonX, buttonY, buttonWidth, buttonHeight);

  // Button outline
  ctx.strokeStyle = '#2c3e50';
  ctx.lineWidth = 2;
  ctx.strokeRect(buttonX, buttonY, buttonWidth, buttonHeight);

  // Button text
  ctx.fillStyle = cfg.buttonTextColor;
  ctx.font = `${cfg.fontSize * 0.8}px ${cfg.fontFamily}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Restart', buttonX + buttonWidth / 2, buttonY + buttonHeight / 2);
}

/**
 * Renders the order completion button (appears when resources are sufficient)
 */
export function renderOrderButton(
  ctx: CanvasRenderingContext2D,
  state: HUDState,
  canvasWidth: number,
  canvasHeight: number,
  config: Partial<RenderUIConfig> = {}
): void {
  const cfg = { ...DEFAULT_UI_CONFIG, ...config };

  if (!state.orderButtonHighlighted) return;

  const barHeight = 60;
  const buttonWidth = 120;
  const buttonHeight = 40;
  const buttonX = canvasWidth - 130;
  const buttonY = barHeight / 2 - 20;

  // Highlighted button background
  ctx.fillStyle = cfg.buttonHighlightedColor;
  ctx.fillRect(buttonX, buttonY, buttonWidth, buttonHeight);

  // Button outline
  ctx.strokeStyle = '#1e8449';
  ctx.lineWidth = 3;
  ctx.strokeRect(buttonX, buttonY, buttonWidth, buttonHeight);

  // Button text
  ctx.fillStyle = cfg.buttonHighlightedTextColor;
  ctx.font = `${cfg.fontSize * 0.9}px ${cfg.fontFamily}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Complete Order', buttonX + buttonWidth / 2, buttonY + buttonHeight / 2);
}

/**
 * Renders victory screen overlay
 */
export function renderVictoryScreen(
  ctx: CanvasRenderingContext2D,
  ordersCompleted: number,
  canvasWidth: number,
  canvasHeight: number
): void {
  // Dark overlay
  ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  // Victory text
  ctx.fillStyle = '#27ae60';
  ctx.font = 'bold 48px Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Victory!', canvasWidth / 2, canvasHeight / 2 - 30);

  ctx.fillStyle = '#ffffff';
  ctx.font = '24px Arial, sans-serif';
  ctx.fillText(`Completed ${ordersCompleted} orders`, canvasWidth / 2, canvasHeight / 2 + 10);

  ctx.fillStyle = '#cccccc';
  ctx.font = '18px Arial, sans-serif';
  ctx.fillText('Click or tap to restart', canvasWidth / 2, canvasHeight / 2 + 50);
}

/**
 * Renders a pause overlay on a piece
 */
export function renderPausedOverlay(
  ctx: CanvasRenderingContext2D,
  piecePosition: { x: number; y: number },
  cellSize: number
): void {
  ctx.fillStyle = 'rgba(128, 128, 128, 0.5)';
  ctx.fillRect(piecePosition.x, piecePosition.y, cellSize * 2, cellSize);
}

/**
 * Gets the button area for click detection
 */
export function getRestartButtonBounds(
  canvasWidth: number,
  canvasHeight: number
): { x: number; y: number; width: number; height: number } {
  const buttonWidth = 100;
  const buttonHeight = 35;
  const buttonX = canvasWidth - 110;
  const buttonY = (60 - buttonHeight) / 2;

  return { x: buttonX, y: buttonY, width: buttonWidth, height: buttonHeight };
}

/**
 * Gets the order button area for click detection
 */
export function getOrderButtonBounds(
  canvasWidth: number
): { x: number; y: number; width: number; height: number } | null {
  // Order button appears on the right
  return {
    x: canvasWidth - 130,
    y: 15,
    width: 120,
    height: 40,
  };
}