/**
 * Canvas setup, resize handling, and DPI scaling for crisp rendering.
 */

export interface CanvasConfig {
  /** CSS size of canvas element */
  cssWidth: number;
  cssHeight: number;
  /** Device pixel ratio for high-DPI displays */
  dpr: number;
  /** Whether to auto-resize on window changes */
  autoResize: boolean;
}

/**
 * Creates and configures the game canvas
 */
export function createCanvas(container: HTMLElement): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.id = 'game-canvas';
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.display = 'block';

  // Prevent selection and context menu
  canvas.addEventListener('contextmenu', e => e.preventDefault());
  canvas.addEventListener('selectstart', e => e.preventDefault());

  container.appendChild(canvas);
  return canvas;
}

/**
 * Gets the current device pixel ratio
 */
export function getDevicePixelRatio(): number {
  return window.devicePixelRatio || 1;
}

/**
 * Resizes canvas to match container while maintaining internal resolution
 */
export function resizeCanvas(
  canvas: HTMLCanvasElement,
  container: HTMLElement,
  config: CanvasConfig
): { width: number; height: number } {
  const dpr = config.dpr || getDevicePixelRatio();

  // Get container size
  const rect = container.getBoundingClientRect();
  const cssWidth = rect.width;
  const cssHeight = rect.height;

  // Set canvas internal size (backing store)
  canvas.width = Math.floor(cssWidth * dpr);
  canvas.height = Math.floor(cssHeight * dpr);

  // Set canvas CSS size
  canvas.style.width = `${cssWidth}px`;
  canvas.style.height = `${cssHeight}px`;

  // Scale context for high-DPI rendering
  const ctx = canvas.getContext('2d')!;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  return { width: cssWidth, height: cssHeight };
}

/**
 * Sets up resize observer for auto-resizing
 */
export function setupResizeObserver(
  canvas: HTMLCanvasElement,
  container: HTMLElement,
  config: CanvasConfig,
  onResize: (width: number, height: number) => void
): ResizeObserver | null {
  if (!config.autoResize) return null;

  const observer = new ResizeObserver(() => {
    const { width, height } = resizeCanvas(canvas, container, config);
    onResize(width, height);
  });

  observer.observe(container);
  return observer;
}

/**
 * Clears the canvas with optional background color
 */
export function clearCanvas(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  color: string = '#1a1a2e'
): void {
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, width, height);
}

/**
 * Translates canvas coordinates to world coordinates
 */
export function screenToWorld(
  screenX: number,
  screenY: number,
  canvas: HTMLCanvasElement,
  worldOffsetX: number,
  worldOffsetY: number,
  worldScale: number
): { x: number; y: number } {
  const rect = canvas.getBoundingClientRect();
  const canvasX = screenX - rect.left;
  const canvasY = screenY - rect.top;

  return {
    x: (canvasX - worldOffsetX) / worldScale,
    y: (canvasY - worldOffsetY) / worldScale,
  };
}

/**
 * Translates world coordinates to screen coordinates
 */
export function worldToScreen(
  worldX: number,
  worldY: number,
  canvas: HTMLCanvasElement,
  worldOffsetX: number,
  worldOffsetY: number,
  worldScale: number
): { x: number; y: number } {
  const rect = canvas.getBoundingClientRect();

  return {
    x: worldX * worldScale + worldOffsetX + rect.left,
    y: worldY * worldScale + worldOffsetY + rect.top,
  };
}

/**
 * Checks if a point is inside a rectangle
 */
export function pointInRect(
  x: number,
  y: number,
  rectX: number,
  rectY: number,
  rectWidth: number,
  rectHeight: number
): boolean {
  return x >= rectX && x <= rectX + rectWidth && y >= rectY && y <= rectY + rectHeight;
}

/**
 * Creates an offscreen canvas for rendering sprites/shapes
 */
export function createOffscreenCanvas(width: number, height: number, dpr: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = Math.floor(width * dpr);
  canvas.height = Math.floor(height * dpr);
  const ctx = canvas.getContext('2d')!;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return canvas;
}