/**
 * Resource queue logic, rate-limited ports, blockage detection.
 * All resources move from output ports to input ports, supporting both
 * direct port-to-port transfer and transfer through intermediate Conveyor cells.
 */

import {
  Piece,
  Resource,
  Connection,
} from './types.js';

// Maximum simultaneous resources on field (bounded performance)
export const MAX_RESOURCE_UNITS = 100;

/**
 * Processes one tick of resource movement across the field.
 * Returns moved resources and any blockages.
 */
export function processResourceFlow(
  pieces: Piece[],
  connections: Connection[],
  movedResources: Resource[] = []
): {
  blockages: Array<{
    chainId: string;
    blockedPort: any;
    blockedResources: Resource[];
  }>;
  activities: Array<{
    pieceId: string;
    actions: ('produced' | 'consumed' | 'transferred')[];
  }>;
} {
  const blockages: any[] = [];
  const activities: any[] = [];

  // 1. Process Source Piece throughput
  for (const piece of pieces.filter(p => p.type === 'source')) {
    const outputs = processSourcePiece(piece, connections);
    movedResources.push(...outputs.moved);
    activities.push(...outputs.activities);
    blockages.push(...outputs.blockages);
  }

  // 2. Process Conveyor cell movement
  for (const piece of pieces.filter(p => p.type === 'conveyor')) {
    const outputs = processConveyorPiece(piece, connections);
    movedResources.push(...outputs.moved);
    activities.push(...outputs.activities);
    blockages.push(...outputs.blockages);
  }

  // 3. Process Processor conversion
  for (const piece of pieces.filter(p => p.type === 'processor')) {
    const outputs = processProcessorPiece(piece, connections);
    movedResources.push(...outputs.moved);
    activities.push(...outputs.activities);
    blockages.push(...outputs.blockages);
  }

  // 4. Process Container output
  for (const piece of pieces.filter(p => p.type === 'container')) {
    const outputs = processContainerPiece(piece, connections);
    movedResources.push(...outputs.moved);
    activities.push(...outputs.activities);
    blockages.push(...outputs.blockages);
  }

  return {
    blockages,
    activities,
  };
}

/**
 * Process Source Piece: outputs 1 apple per second per output port
 */
function processSourcePiece(
  piece: Piece,
  connections: Connection[]
): {
  moved: Resource[];
  activities: Array<{ pieceId: string; actions: ('produced' | 'consumed' | 'transferred')[] }>;
  blockages: any[];
} {
  const moved: Resource[] = [];
  const activities: any[] = [];
  const blockages: any[] = [];

  // Source pieces have fixed 8 apples initially (2 per cell)
  // Throughput: 1 apple/second across all ports
  const currentApples = piece.resources.apple || 0;

  // Output to each connected conveyor (max 1 per tick total)
  const outputConnections = connections.filter(
    c => c.sourcePieceId === piece.id && c.sourcePort.type === 'output' && c.targetPieceId !== 'perimeter'
  );

  if (outputConnections.length > 0 && currentApples > 0) {
    // Produce 1 apple per tick (simplified)
    // For simplicity, produce 1 apple per processSourcePiece call

    const newResource: Resource = {
      id: `res_src_${piece.id}_${Date.now()}`,
      type: 'apple',
      currentCell: { row: piece.position.row, col: piece.position.col },
      currentPieceId: piece.id,
      nextCell: { row: 0, col: 0 },
      queueIndex: 0,
      generationTime: Date.now(),
    };

    // Decrement apples
    piece.resources.apple = currentApples - 1;

    moved.push(newResource);
    activities.push({
      pieceId: piece.id,
      actions: ['produced', 'transferred'],
    });
  }

  // If all apples are exhausted, mark for removal
  if (currentApples <= 0) {
    blockages.push({ message: 'Source depleted', sourcePiece: piece.id });
  }

  return { moved, activities, blockages };
}

/**
 * Process Conveyor Piece: moves 1 cell per second per resource
 */
function processConveyorPiece(
  piece: Piece,
  connections: Connection[]
): {
  moved: Resource[];
  activities: Array<{ pieceId: string; actions: ('produced' | 'consumed' | 'transferred')[] }>;
  blockages: any[];
} {
  const moved: Resource[] = [];
  const activities: any[] = [];
  const blockages: any[] = [];

  // Count resources on this conveyor
  const currentApples = piece.resources.apple || 0;
  const currentSlices = piece.resources['apple_slice'] || 0;
  const totalResources = currentApples + currentSlices;

  if (totalResources === 0) {
    return { moved, activities, blockages };
  }

  // Conveyor capacity: 1 resource per cell
  // For 1x2 conveyor, max 2 resources
  const cellCount = piece.variant.shape.length || 1;
  const maxCapacity = cellCount;

  // Find input connection (where resources enter)
  const inputConns = connections.filter(
    c => c.targetPieceId === piece.id
  );

  // Accept new resources if there's room
  for (const conn of inputConns) {
    if (totalResources >= maxCapacity) break;

    // Create a new resource entering this conveyor
    const newResource: Resource = {
      id: `res_conv_${piece.id}_${Date.now()}`,
      type: 'apple',
      currentCell: { row: piece.position.row, col: piece.position.col },
      currentPieceId: piece.id,
      nextCell: { row: 0, col: 0 },
      queueIndex: totalResources,
      generationTime: Date.now(),
    };

    moved.push(newResource);
    activities.push({
      pieceId: piece.id,
      actions: ['transferred'],
    });
  }

  return { moved, activities, blockages };
}

/**
 * Process Processor Piece: converts 1 apple to 1 apple slice per 2 seconds
 */
function processProcessorPiece(
  piece: Piece,
  connections: Connection[]
): {
  moved: Resource[];
  activities: Array<{ pieceId: string; actions: ('produced' | 'consumed' | 'transferred')[] }>;
  blockages: any[];
} {
  const moved: Resource[] = [];
  const activities: any[] = [];
  const blockages: any[] = [];

  // If there's no input apple, check for one arriving
  if (!piece.processorInput) {
    const inputConns = connections.filter(
      c => c.targetPieceId === piece.id
    );

    if (inputConns.length > 0) {
      // Accept an apple into processing
      piece.processorInput = {
        id: `${piece.id}_proc_${Date.now()}`,
        type: 'apple',
        currentCell: { row: piece.position.row, col: piece.position.col },
        currentPieceId: piece.id,
        generationTime: Date.now(),
      };

      activities.push({
        pieceId: piece.id,
        actions: ['consumed'],
      });
    }
  }

  // If there's an apple in progress, continue processing
  if (piece.processorInput) {
    piece.processorProgress = (piece.processorProgress || 0) + 1;

    // Complete processing after 120 ticks (2 seconds at 60Hz)
    if (piece.processorProgress >= 120) {
      // Convert apple to apple slice
      const outputResource: Resource = {
        id: `${piece.id}_slice_${Date.now()}`,
        type: 'apple_slice',
        currentCell: { row: piece.position.row, col: piece.position.col },
        currentPieceId: piece.id,
        nextCell: null,
        queueIndex: 0,
        generationTime: Date.now(),
      };

      piece.processorOutput = outputResource;

      activities.push({
        pieceId: piece.id,
        actions: ['produced', 'transferred'],
      });
    }
  }

  // Output the apple slice if there's one ready
  if (piece.processorOutput) {
    moved.push(piece.processorOutput);
    piece.processorOutput = null;
    // Reset processor input
    piece.processorInput = null;
  }

  return { moved, activities, blockages };
}

/**
 * Process Container Piece: store resources with type lock
 */
function processContainerPiece(
  piece: Piece,
  connections: Connection[]
): {
  moved: Resource[];
  activities: Array<{ pieceId: string; actions: ('produced' | 'consumed' | 'transferred')[] }>;
  blockages: any[];
} {
  const moved: Resource[] = [];
  const activities: any[] = [];
  const blockages: any[] = [];

  const currentStorage = piece.containerStorage || [];
  const containerType = piece.containerType;
  const CAPACITY = 12;

  // Input connections
  const inputConns = connections.filter(
    c => c.targetPieceId === piece.id
  );

  // Check for new incoming resources
  for (const conn of inputConns) {
    if (currentStorage.length >= CAPACITY) break;

    // If container is empty, accept first resource type
    if (currentStorage.length === 0 && containerType === null) {
      // Accept this resource type (default to apple for now)
      const resource: Resource = {
        id: `res_container_${piece.id}_${Date.now()}`,
        type: 'apple',
        currentCell: { row: piece.position.row, col: piece.position.col },
        currentPieceId: piece.id,
        nextCell: null,
        queueIndex: 0,
        generationTime: Date.now(),
      };

      piece.containerType = 'apple';
      piece.containerStorage.push(resource);
      activities.push({
        pieceId: piece.id,
        actions: ['transferred'],
      });
    } else if (containerType && currentStorage.length < CAPACITY) {
      // Accept same resource type
      const resource: Resource = {
        id: `res_container_${piece.id}_${Date.now()}`,
        type: containerType,
        currentCell: { row: piece.position.row, col: piece.position.col },
        currentPieceId: piece.id,
        nextCell: null,
        queueIndex: currentStorage.length,
        generationTime: Date.now(),
      };

      piece.containerStorage.push(resource);
      activities.push({
        pieceId: piece.id,
        actions: ['transferred'],
      });
    } else if (containerType) {
      // Block - cannot accept different resource type
      blockages.push({
        message: 'Container type lock prevents different resource',
        containerId: piece.id,
      });
    }
  }

  // Check output - resources can leave through output ports
  if (currentStorage.length > 0) {
    activities.push({
      pieceId: piece.id,
      actions: ['transferred'],
    });
  }

  return { moved, activities, blockages };
}